// Sibling view leaves SillyTavern's message DOM and saved MVU data intact.
function createMvuHistoryDisplay() {
  const views = new Map();
  let style;
  const clear = () => {
    for (const view of views.values()) view.remove();
    views.clear();
    style?.remove();
    style = undefined;
  };

  function createFoldCard(doc, summaryText) {
    const details = doc.createElement('details');
    details.dataset.taView = 'record';
    details.className = 'transam-fold';
    details.style.cssText = 'box-sizing:border-box;min-width:0;max-width:100%;margin:6px 0;border:1px solid var(--SmartThemeBorderColor,var(--SmartThemeQuoteColor,currentColor));border-left:1px solid var(--SmartThemeBorderColor,color-mix(in srgb,currentColor 20%,transparent));border-radius:3px 12px 3px 3px;background:var(--SmartThemeBlurTintColor,transparent);color:var(--SmartThemeBodyColor,inherit);box-shadow:0 5px 16px rgba(0,0,0,.16);overflow-wrap:anywhere;';

    const summaryEl = doc.createElement('summary');
    summaryEl.style.cssText = 'box-sizing:border-box;min-height:54px;padding:9px 13px;cursor:pointer;list-style-position:inside;color:var(--SmartThemeBodyColor,inherit);line-height:1.35;';

    const spanWrap = doc.createElement('span');
    spanWrap.style.cssText = 'display:inline-block;vertical-align:middle;max-width:calc(100% - 26px);';

    const tagSpan = doc.createElement('span');
    tagSpan.style.cssText = 'display:block;margin-bottom:5px;font:10px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.12em;color:inherit;';
    tagSpan.textContent = '05 / TRANS-AM · TURN RECORD';
    spanWrap.appendChild(tagSpan);

    const dateMatch = summaryText.match(/(?:第[〇零一二三四五六七八九十百千两\d]+[日天][ \t]*(?:[上下]午|凌晨|清晨|早晨|中午|傍晚|黄昏|晚上|深夜)?[ \t]*\d{1,2}[:：]\d{2}(?:[ \t]*(?:至|到|—|–|~|～|-)[ \t]*(?:(?:第[〇零一二三四五六七八九十百千两\d]+[日天])[ \t]*)?\d{1,2}[:：]\d{2})?|(?:\d{4}(?:[\/-]\d{1,2}[\/-]\d{1,2}|年\d{1,2}月\d{1,2}日)|[\u3400-\u9fff]{1,16}(?:元|[〇零一二三四五六七八九十百千两\d]{1,8})年(?:[\/-]\d{1,2}[\/-]\d{1,2}|[〇零一二三四五六七八九十廿卅\d]{1,3}月[〇零一二三四五六七八九十廿卅\d]{1,3}日))(?:[ T\t]*(?:\d{1,2}[:：]\d{2}(?::\d{2})?|\d{1,2}时(?:\d{1,2}分)?|凌晨|清晨|早晨|上午|中午|下午|傍晚|黄昏|晚上|深夜))?)/);
    if (dateMatch) {
      const dateSpan = doc.createElement('span');
      dateSpan.style.cssText = 'display:block;margin-bottom:5px;font:10px/1.4 ui-monospace,SFMono-Regular,Consolas,monospace;letter-spacing:.12em;color:var(--SmartThemeBodyColor,inherit);overflow-wrap:anywhere;';
      dateSpan.textContent = dateMatch[0];
      spanWrap.appendChild(dateSpan);
    }

    const titleSpan = doc.createElement('span');
    titleSpan.style.cssText = 'display:block;font-size:14px;line-height:1.55;font-weight:650;letter-spacing:.035em;color:var(--SmartThemeBodyColor,inherit);';
    titleSpan.textContent = '本轮存档';
    spanWrap.appendChild(titleSpan);

    summaryEl.appendChild(spanWrap);
    details.appendChild(summaryEl);

    const contentDiv = doc.createElement('div');
    contentDiv.className = 'ta-history-mvu-summary-body';
    contentDiv.style.cssText = 'box-sizing:border-box;min-width:0;margin:0 13px 10px;padding:9px 0 0;border-top:1px solid var(--SmartThemeBorderColor,var(--SmartThemeQuoteColor,currentColor));font-size:.94em;line-height:1.85;color:var(--SmartThemeBodyColor,inherit);overflow-wrap:anywhere;white-space:pre-wrap;';
    contentDiv.textContent = summaryText;
    details.appendChild(contentDiv);

    return details;
  }

  function sync(summaries) {
    if (!summaries.size) { clear(); return; }
    const doc = window.parent?.document ?? window.document;
    if (!doc?.head || !doc.defaultView?.CSS?.supports('selector(:has(+ *))')) return;

    if (!style?.isConnected) {
      style = doc.createElement('style');
      style.textContent = `
        .ta-history-mvu-summary + .mes_text:not(:has(.edit_textarea)):not(.ta-mvu-preview-open),
        .ta-history-mvu-summary:has(+ .mes_text .edit_textarea),
        .ta-history-mvu-summary:has(+ .mes_text.ta-mvu-preview-open) { display: none !important; }
        .ta-history-mvu-summary { overflow-wrap: anywhere; }
      `;
      doc.head.append(style);
    }

    const seen = new Set();
    for (const row of doc.querySelectorAll('#chat > .mes[mesid]')) {
      const id = Number(row.getAttribute('mesid'));
      const summary = summaries.get(id);
      if (!summary) continue;
      const body = row.querySelector('.mes_block > .mes_text');
      if (!body) continue;
      seen.add(row);
      let view = views.get(row);
      if (!view) {
        view = doc.createElement('div');
        view.className = 'ta-history-mvu-summary';
        views.set(row, view);
      }
      if (view.nextElementSibling !== body) body.before(view);
      if (view.__taSummary !== summary) {
        view.replaceChildren(createFoldCard(doc, summary));
        view.__taSummary = summary;
      }
    }
    for (const [row, view] of views) {
      if (seen.has(row)) continue;
      view.remove();
      views.delete(row);
    }
  }

  return { sync, clear };
}
// Selected swipe only. Original messages remain in transam_history_window backups.
(() => {
  const mvuDisplay = createMvuHistoryDisplay();
  const key = 'transam_history_window';
  /* Individual 查看原文 toggle for already-compacted history rows.
     Injected into the 4A history-window script. This module only reads rows and
     writes a local DOM preview: it never writes chat messages or prompts. */
  function createHistoryPreview({
    key,
    doc = (() => {
      try { return (typeof window !== 'undefined' && window.parent?.document) || document; }
      catch { return typeof document !== 'undefined' ? document : undefined; }
    })(),
  } = {}) {
    const STYLE_ID = 'ta-history-original-style';
    const FOOTER_CLASS = 'ta-history-original';
    const BUTTON_CLASS = 'ta-history-original-toggle';
    const CONTENT_CLASS = 'ta-history-original-content';
    const DRAG_SLOP = 10;
    /** @type {Map<string, string>} mesid -> exact original text of expanded rows */
    const expanded = new Map();
    let rows = [];
    let enabled = false;
    let chatId;
    let mvuIds = new Set();
    let observer;
    let observedRoot;
    let scheduled = false;
    let disposed = false;

    const chatRoot = () => doc.querySelector('#chat');
    const isMvu = row => mvuIds.has(mesidOf(row));
    const savedFor = row => row?.extra?.[key];
    const eligible = row => {
      if (isMvu(row)) return true;
      const saved = savedFor(row);
      return Boolean(saved && row.message === saved.compact && typeof saved.original === 'string');
    };
    const mesidOf = row => String(row.message_id);

    /** Add the small theme-aware style once. @returns {void} */
    const ensureStyle = () => {
      if (doc.getElementById(STYLE_ID)) return;
      const style = doc.createElement('style');
      style.id = STYLE_ID;
      style.textContent = `
        .${FOOTER_CLASS}{display:flex;flex-direction:column;align-items:flex-start;gap:4px;margin:2px 0 6px}
        .${BUTTON_CLASS}{font:inherit;font-size:12px;line-height:1.4;min-height:24px;padding:1px 8px;border:1px solid var(--SmartThemeBorderColor,rgba(128,128,128,.45));border-radius:999px;background:transparent;color:var(--SmartThemeQuoteColor,inherit);cursor:pointer;touch-action:manipulation;opacity:.82}
        .${BUTTON_CLASS}:hover,.${BUTTON_CLASS}:focus-visible{opacity:1;outline:1px solid var(--SmartThemeBorderColor,rgba(128,128,128,.45));outline-offset:1px}
        .${CONTENT_CLASS}{width:100%;max-height:60vh;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:.92em;line-height:1.5;padding:6px 8px;border-left:2px solid var(--SmartThemeBorderColor,rgba(128,128,128,.45));color:var(--SmartThemeBodyColor,inherit);background:var(--SmartThemeBlurTintColor,transparent);border-radius:0 4px 4px 0}
      `;
      (doc.head || doc.documentElement).appendChild(style);
    };
    const removeStyle = () => doc.getElementById(STYLE_ID)?.remove();
    /** @returns {Map<string, object>} eligible rows by mesid for the current pass */
    const eligibleRows = () => new Map(rows.filter(eligible).map(row => [mesidOf(row), row]));

    /** Remove preview footers from a message block. @param {Element|undefined} block @returns {void} */
    const removeFooters = block => {
      if (!block) return;
      const text = block.querySelector(':scope > .mes_text') || block.querySelector('.mes_text');
      if (text) text.classList.remove('ta-mvu-preview-open');
      for (const el of Array.from(block.children)) {
        if (el.classList?.contains(FOOTER_CLASS)) el.remove();
      }
    };
    /** Remove every preview footer and the style from the document. @returns {void} */
    const clearDom = () => {
      for (const el of Array.from(doc.querySelectorAll('.ta-mvu-preview-open'))) el.classList.remove('ta-mvu-preview-open');
      for (const el of Array.from(doc.querySelectorAll(`.${FOOTER_CLASS}`))) el.remove();
      removeStyle();
    };
    const detachObserver = () => {
      observer?.disconnect();
      observer = undefined;
      observedRoot = undefined;
    };

    /**
