// SillyTavern 1.19.0 + Tavern Helper 4.11.3; normal completed streams only.
(() => {
  let active = null;
  let chain = null;
  let timer;
  let serial = 0;
  const context = () => SillyTavern.getContext();
  const enabled = id => { const prompts = getPreset('in_use').prompts; return (prompts.find(p => p.id === id) ?? prompts.find(p => p.id === id.replace(/^ta-/, 'tw-')))?.enabled === true; };
  const incomplete = text => {
    if (/^\s*(?:\{|```(?:json)?\s*\{)/i.test(text)) return false;
    text = text.replace(/```[\s\S]*?(?:```|$)/g, '').replace(/`[^`\r\n]*`/g, '');
    if (!/<(?:ta|tw)_(?:zh|source|plan)\b[^>]*>/i.test(text)) return false;
    // The body is the completion target; optional records and choices never force another request.
    const tags = [...text.matchAll(/<(\/?)(?:ta|tw)_zh\s*>/gi)];
    if (tags.length) {
      let depth = 0;
      for (const tag of tags) depth += tag[1] ? -1 : 1;
      return depth > 0;
    }
    return true; // A brief/source-only response still owes the required Chinese body.
  };
  const cancel = () => { serial++; clearTimeout(timer); active = null; chain = null; };
  const listeners = [
    eventOn(tavern_events.GENERATION_STARTED, (type, options, dryRun) => {
      if (dryRun) return; // Prompt previews must not cancel a real continuation chain.
      clearTimeout(timer);
      serial++;
      const st = context();
      active = null;
      if (dryRun || window.parent.__TA_MANUAL_CONTINUE_V1__?.active || st.groupId || !enabled('ta-auto-continue') || enabled('ta-ooc-review') || ![undefined, 'normal', 'regenerate', 'swipe', 'continue'].includes(type)) { chain = null; return; }
      if (type !== 'continue') chain = null;
      active = { serial, chat: st.chat, chatId: st.getCurrentChatId(), previous: st.chat.at(-1), text: st.chat.at(-1)?.mes, swipe: st.chat.at(-1)?.swipe_id };
    }),
    eventOn(tavern_events.GENERATION_STOPPED, cancel),
    eventOn(tavern_events.CHAT_CHANGED, cancel),
    eventOn(tavern_events.GENERATION_ENDED, () => {
      if (!active) return;
      const run = active;
      active = null;
      const st = context();
      const stream = st.streamingProcessor;
      // Generation-ended also fires on errors; require the host's successful stream flag.
      if (!stream?.isFinished || stream.isStopped || stream.abortController?.signal.aborted) { chain = null; return; }
      timer = setTimeout(async () => {
        const current = context();
        const last = current.chat.at(-1);
        const ttState = (window.parent?.__taTwinTailInterceptor__ || window.__taTwinTailInterceptor__)?.getContinueTransportState?.();
        if (window.parent.__TA_MANUAL_CONTINUE_V1__?.active || (ttState && ttState.activeRunCount > 0) || serial !== run.serial || current.chat !== run.chat || current.getCurrentChatId() !== run.chatId || current.groupId || !enabled('ta-auto-continue') || enabled('ta-ooc-review')) return;
        if (!last || last.is_user || last.is_system || (last === run.previous && last.mes === run.text && last.swipe_id === run.swipe)) return;
        if (!incomplete(last.mes)) { chain = null; return; }
        if (current.substituteParams('{{input}}').trim()) { chain = null; return; }
        if (!chain || chain.message !== last || chain.swipe !== last.swipe_id) chain = { message: last, swipe: last.swipe_id, count: 0 };
