})();

// SillyTavern 1.19.0 / Tavern Helper 4.11.3. Non-stealth: host returns results to the model.
(() => {
  const name = 'transam_decide';
  const context = () => SillyTavern.getContext();
  const enabled = id => getPreset('in_use').prompts.some(p => p.id === id && p.enabled);
  const normalize = value => value.normalize('NFKC').toLowerCase().replace(/\s+/g, ' ').trim();
  let turn = null;
  let active = null;
  const error = (code, message) => JSON.stringify({ ok: false, code, message });
  const allowed = () => enabled('ta-decision-tool') && enabled('ta-random-reaction') && !enabled('ta-ooc-review') && !context().groupId;
  const random10000 = () => {
    if (!globalThis.crypto?.getRandomValues) throw new Error('Secure randomness unavailable');
    const value = new Uint32Array(1), limit = Math.floor(4294967296 / 10000) * 10000;
    do { crypto.getRandomValues(value); } while (value[0] >= limit);
    return value[0] % 10000 + 1;
  };
  // Keep Google function responses separate from trailing preset instructions.
  function relocateDecisionGoogleSuffix(chat, source) {
    const isGoogle = ['vertexai', 'makersuite'].includes(source) || String(source || '').toLowerCase().includes('vertex') || String(source || '').toLowerCase().includes('makersuite');
    if (!isGoogle || !Array.isArray(chat)) return false;
    let end = chat.length - 1;
    while (end >= 0 && chat[end].role !== 'tool') end--;
    if (end < 0 || end === chat.length - 1) return false;
    let call = end;
    while (call >= 0 && chat[call].role === 'tool') call--;
    const message = chat[call];
    if (message?.role !== 'assistant' || !Array.isArray(message.tool_calls)
        || !message.tool_calls.some(x => x.function?.name === 'transam_decide')) return false;
    const expected = message.tool_calls.map(x => x.id);
    const results = chat.slice(call + 1, end + 1).map(x => x.tool_call_id);
    if (new Set(expected).size !== expected.length || expected.length !== results.length
        || new Set(results).size !== results.length || !expected.every(id => results.includes(id))) return false;
    const suffix = chat.splice(end + 1);
    chat.splice(call, 0, ...suffix);
    return true;
  }
  const listeners = [
    eventOn(tavern_events.CHAT_COMPLETION_PROMPT_READY, ({ chat, dryRun }) => {
      if (enabled('ta-decision-tool')) {
        // The fast pool is already expanded here. Keep it out of the independent decision request.
        const hideFastPool = text => text.replace(/<ta_rule_reaction_dice_pool>[\s\S]*?<\/ta_rule_reaction_dice_pool>/g, 'Independent draw: commit candidates before rolling. No fast pool.');
        for (const message of chat) {
          if (message.role === 'tool') continue;
          if (typeof message.content === 'string') message.content = hideFastPool(message.content);
          else if (Array.isArray(message.content)) {
            for (const part of message.content) {
              if (part.type === 'text') part.text = hideFastPool(part.text);
            }
          }
        }
      }
      if (!dryRun && active && allowed()) relocateDecisionGoogleSuffix(chat, context().chatCompletionSettings?.chat_completion_source);
    }),
    eventOn(tavern_events.GENERATION_STARTED, (type, options, dryRun) => {
      if (dryRun) return;
      active = null;
      const st = context();
      if (!allowed() || ![undefined, 'normal', 'regenerate'].includes(type)) return;
      const user = [...st.chat].reverse().find(m => m.is_user && !m.is_system);
      if (!turn || type === 'regenerate' || turn.chatId !== st.getCurrentChatId() || turn.chat !== st.chat || turn.user !== user || turn.userText !== user?.mes || turn.userSwipe !== user?.swipe_id) {
        turn = { chatId: st.getCurrentChatId(), chat: st.chat, user, userText: user?.mes, userSwipe: user?.swipe_id, cache: new Map(), npcDraws: 0, playerDraws: 0 };
      }
      active = turn;
    }),
    eventOn(tavern_events.CHAT_CHANGED, () => { active = null; turn = null; }),
    eventOn(tavern_events.GENERATION_STOPPED, () => { active = null; }),
  ];
  if (context().ToolManager.tools.some(t => t.toFunctionOpenAI().function.name === name)) throw new Error('TRANS-AM decision tool already registered');
  context().registerFunctionTool({
    name, displayName: 'TRANS-AM 决策抽签',
    description: 'Commit one acting character’s alternatives and relative weights FIRST; this tool then draws a fresh hidden number and returns exact probabilities and one selected action. Submit one option for a sole credible action (no roll); otherwise only genuinely different available actions, not a fixed three. Wait for this result before writing the scene or calling transam_content. Use actor=npc for up to three NPC draws, or actor=player for one draw authorized by AUTOWRITE. Preserve prior results.',
    parameters: { type: 'object', properties: {
      actor: { type: 'string', enum: ['npc', 'player'], description: 'Defaults to npc. Player requires active AUTOWRITE and an authorized player decision.' },
      npc: { type: 'string', maxLength: 100, description: 'Name of the acting character.' }, focus: { type: 'string', maxLength: 240 },
      options: { type: 'array', minItems: 1, maxItems: 8, items: { type: 'object', properties: { id: { type: 'string', maxLength: 32 }, action: { type: 'string', maxLength: 240 }, support: { type: 'string', maxLength: 240, description: 'A brief established character/scene fact supporting this action; not private reasoning.' }, weight: { type: 'number', minimum: 0.000001, maximum: 1000000, description: 'Positive relative likelihood, not a prefilled percentage template. Values need not sum to 100.' } }, required: ['id', 'action', 'support', 'weight'], additionalProperties: false } },
    }, required: ['npc', 'focus', 'options'], additionalProperties: false },
    stealth: false, formatMessage: () => '提交角色分支后抽签',
    shouldRegister: () => !!active && allowed() && active.chat === context().chat && active.chatId === context().getCurrentChatId(),
    action: args => {
      if (!active || !allowed() || active.chat !== context().chat || active.chatId !== context().getCurrentChatId()) return error('inactive', 'No active decision request. Do not invent a result.');
      if (!args || Object.keys(args).some(k => !['actor', 'npc', 'focus', 'options'].includes(k)) || typeof args.npc !== 'string' || !args.npc.trim() || args.npc.length > 100 || typeof args.focus !== 'string' || !args.focus.trim() || args.focus.length > 240 || !Array.isArray(args.options) || args.options.length < 1 || args.options.length > 8) return error('invalid_request', 'Supply NPC, one decision focus, and 1–8 genuine alternatives. Do not pad alternatives.');
      const actor = args.actor ?? 'npc';
      if (!['npc', 'player'].includes(actor)) return error('invalid_actor', 'Choose npc or player as the acting side.');
      if (actor === 'player' && (!enabled('ta-player-autowrite') || enabled('ta-player-guard'))) {
        return error('player_not_authorized', 'A player draw requires active AUTOWRITE.');
      }
      const ids = new Set(), actions = new Set();
      for (const option of args.options) {
        if (!option || Object.keys(option).some(k => !['id', 'action', 'support', 'weight'].includes(k)) || !['id', 'action', 'support'].every(k => typeof option[k] === 'string' && option[k].trim()) || option.id.length > 32 || option.action.length > 240 || option.support.length > 240 || !Number.isFinite(option.weight) || option.weight < 0.000001 || option.weight > 1000000) return error('invalid_option', 'Each alternative needs an ID, concrete action, brief grounded support and finite positive relative weight.');
        const id = normalize(option.id), action = normalize(option.action);
        if (ids.has(id) || actions.has(action)) return error('duplicate_option', 'Merge duplicate alternatives before drawing.');
        ids.add(id); actions.add(action);
