      const key = actor + '\n' + normalize(args.npc) + '\n' + normalize(args.focus);
      const commitment = JSON.stringify(args.options);
      const cached = active.cache.get(key);
      if (cached) return JSON.stringify(cached.commitment === commitment ? { ...cached.result, replayed: true } : { ok: false, code: 'decision_locked', message: 'This NPC decision is already resolved; preserve its committed alternatives and result.', previous: cached.result });
      if (active.cache.size >= 8) return error('turn_limit', 'Use the decisions already recorded for this turn.');
      if (args.options.length > 1 && (actor === 'player' ? active.playerDraws >= 1 : active.npcDraws >= 3)) {
        return error('draw_limit', 'Use the committed results for this side of the scene.');
      }
      const sum = args.options.reduce((total, option) => total + option.weight, 0);
      const quotas = args.options.map(option => option.weight / sum * 10000);
      if (quotas.some(q => q < 1)) return error('resolution_limit', 'An alternative is below the 0.01% resolution. Reconsider the estimates; do not silently round it away.');
      const widths = quotas.map(Math.floor);
      const rank = quotas.map((q, i) => ({ i, fraction: q - widths[i] })).sort((a, b) => b.fraction - a.fraction || a.i - b.i);
      for (let left = 10000 - widths.reduce((a, b) => a + b, 0), i = 0; i < left; i++) widths[rank[i].i]++;
