      let roll = null;
      if (options.length > 1) { try { roll = random10000(); } catch { return error('random_unavailable', 'Secure randomness is unavailable. Do not fabricate a draw.'); } }
      const selected = options.find(option => roll == null || (roll >= option.from && roll <= option.to));
