      should_stream: true,
      should_silence: true,
      max_chat_history: 0,
      ordered_prompts: [
        { role: 'system', content: bigSummaryRequestMark + '\n' + summaryArchiveTaskPrompt },
        { role: 'user', content: body },
      ],
      }).catch(error => {
