    if (quickDisposed || epoch !== summaryProgressEpoch || bigSummaryContext()?.chat !== chat || summaryChatScope() !== scope) return;
    const rows = bigSummaryRows(chat);
    const orphaned = new Set(orphanedSummaryFloors(rows, book, lostRecorded).map(row => row.message_id));
    let through = 0;
    for (const row of rows) {
      if (!isStoryRow(row) || !bigSummaryText(row)) continue;
