    function stDocumentScore(doc) {
        if (!doc?.body) return 0;
        let score = 0;
        try {
            if (doc.getElementById('send_form')) score += 8;
            if (doc.getElementById('send_textarea')) score += 4;
            if (doc.getElementById('sheld')) score += 4;
            if (doc.getElementById('qr--bar')) score += 2;
            if (doc.getElementById('chat')) score += 1;
        } catch (_) {}
        return score;
    }

    function hostDocument() {
        // 按“像不像酒馆主界面”给候选 document 打分再挑：#send_form / #send_textarea 权重最高。
        // 不直接用「谁先有 #chat」判断——外层应用外壳也可能有同名节点，会误挂到看不见的地方。
        // 自己的 document 排在最前，同分时优先自己（酒馆助手沙箱 iframe 自身为空，得分为 0，不会误判）。
        const documents = [];
        const add = host => {
            try {
                const doc = host?.document;
                if (doc?.documentElement && !documents.includes(doc)) documents.push(doc);
            } catch (_) {}
        };
        add(window);
        try {
            if (window.parent && window.parent !== window) add(window.parent);
        } catch (_) {}
        try {
            if (window.top && window.top !== window) add(window.top);
        } catch (_) {}
        for (const h of hostWindows()) add(h);
        let best = null;
        let bestScore = 0;
        for (const doc of documents) {
            const score = stDocumentScore(doc);
            if (score > bestScore) {
                best = doc;
                bestScore = score;
            }
        }
        if (best) return best;
        const visibleBodyDoc = documents.find(doc => doc.body && doc !== document);
        return visibleBodyDoc || documents.find(doc => doc.body) || documents[0] || document;
    }

    function settingsStorage() {
        const doc = hostDocument();
        try { return doc?.defaultView?.localStorage || null; } catch (_) { return null; }
    }

    function notify(level, message, title = SCRIPT_NAME) {
        for (const host of hostWindows()) {
            try {
                const toast = host?.toastr;
                if (toast && typeof toast[level] === 'function') {
                    toast[level](message, title);
                    return;
                }
            } catch (_) {}
        }
        const method = level === 'error' ? 'error' : level === 'warning' ? 'warn' : 'log';
        console[method](`[${SCRIPT_NAME}] ${message}`);
    }


