            if (out.indexOf(han) === -1) continue;
            out = out.split(han).join(zy);
        }
        return out;
    }

    function taRestoreZhuyin(text) {
        if (typeof text !== 'string' || !text || !/[\u3105-\u312F]/.test(text)) return text;
        let out = text;
        for (const [zy, han] of TA_ZHUYIN_RESTORE_PAIRS) {
            if (out.indexOf(zy) === -1) continue;
            out = out.split(zy).join(han);
        }
        return out;
    }

    function taToPinyin(seg) {
        return Array.from(seg).map(c => TA_PINYIN_MAP[c] ? ' ' + TA_PINYIN_MAP[c] + ' ' : c).join('').replace(/ {2,}/g, ' ');
    }

    function taUtf8Base64(str) {
        const bytes = new TextEncoder().encode(String(str ?? ''));
        let bin = '';
        for (let i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
        if (typeof btoa === 'function') return btoa(bin);
        if (typeof Buffer !== 'undefined') return Buffer.from(bytes).toString('base64');
        return str;
    }

    const TA_WI_ID_RX = /^(?:worldInfoBefore|worldInfoAfter|wi_anchor_|worldInfo|lorebook)/i;

    function isStandaloneWorldInfoMsg(m) {
        if (!m || typeof m !== 'object') return false;
        const txt = typeof m.content === 'string'
            ? m.content
            : (Array.isArray(m.content) ? m.content.filter(p => p && p.type === 'text' && typeof p.text === 'string').map(p => p.text).join('\n') : '');
        if (!txt || txt.includes('<ta_rule_') || txt.includes('[TA_NATIVE_DELIVERY]') || txt.includes('<inert_lexical_entropy_buffer') || txt.includes('<ta_roll_pool>')) {
            return false;
        }
        if (m.world_info === true) return true;
        const id = String(m.identifier || m.name || '');
        return Boolean(id && TA_WI_ID_RX.test(id));
    }

    function collectActiveWorldInfoBlocks(messages) {
        const blocks = [];
        const seen = new Set();
        const pushBlock = raw => {
            const str = String(raw ?? '').trim();
            if (!str || str.length < 2) return;
            if (str.includes('<ta_rule_') || str.includes('[TA_NATIVE_DELIVERY]') || str.includes('<inert_lexical_entropy_buffer') || str.includes('<ta_roll_pool>')) return;
            if (seen.has(str)) return;
            seen.add(str);
            blocks.push(str);
        };
        // Layer 1: runtime snapshot from WORLD_INFO_ACTIVATED / CHAT_COMPLETION_PROMPT_READY
        if (runtime.lastPromptReadyChat && Array.isArray(runtime.lastPromptReadyChat.chat) && (Date.now() - (runtime.lastPromptReadyChat.at || 0)) < 15000) {
            for (const m of runtime.lastPromptReadyChat.chat) {
                if (isStandaloneWorldInfoMsg(m)) {
                    const txt = typeof m.content === 'string'
                        ? m.content
                        : (Array.isArray(m.content) ? m.content.filter(p => p && p.type === 'text' && typeof p.text === 'string').map(p => p.text).join('\n') : '');
                    pushBlock(txt);
                }
            }
        }
        if (runtime.lastWorldInfoSnapshot && Array.isArray(runtime.lastWorldInfoSnapshot.blocks)) {
            for (const b of runtime.lastWorldInfoSnapshot.blocks) pushBlock(b);
        }
        // Layer 2: direct messages with world_info === true or worldInfo* identifier
        if (Array.isArray(messages)) {
            for (const m of messages) {
                if (isStandaloneWorldInfoMsg(m)) {
                    const txt = typeof m.content === 'string'
                        ? m.content
                        : (Array.isArray(m.content) ? m.content.filter(p => p && p.type === 'text' && typeof p.text === 'string').map(p => p.text).join('\n') : '');
                    pushBlock(txt);
                }
            }
        }
        // Layer 3: fallback to active character_book plain-text entries
        if (blocks.length === 0) {
            try {
                const stCtx = parentWin.SillyTavern?.getContext?.() || globalThis.SillyTavern?.getContext?.();
                const ch = stCtx?.characters?.[stCtx.characterId];
                const entries = ch?.data?.character_book?.entries;
                const list = Array.isArray(entries) ? entries : (entries && typeof entries === 'object' ? Object.values(entries) : []);
                for (const ent of list) {
                    if (!ent || ent.enabled === false || ent.disable === true) continue;
                    const c = String(ent.content || '').trim();
                    if (!c || c.includes('<%_')) continue;
                    pushBlock(c);
                }
            } catch (_) {}
        }
        return blocks;
    }

    function taEncodeSingleBlock(rawSource, mode, contextKind = false) {
        const str = String(rawSource ?? '');
        if (!str.trim()) return str;
        const kind = contextKind === 'worldinfo' ? 'worldinfo' : (contextKind ? 'history' : false);
        const pilotPfx = str.startsWith('[PILOT_OVERRIDE]') ? '[PILOT_OVERRIDE]\n' : '';
        const rawBody = pilotPfx ? str.slice('[PILOT_OVERRIDE]'.length).replace(/^\r?\n+/, '') : str;
        const body = (mode === 'zhuyin' || mode === 'pinyin' || mode === 'base64' || mode === 'light_ref')
            ? unmaskNSFWTokens(rawBody)
            : rawBody;
        if (!body.trim()) return str;
        if (mode === 'light_ref') {
            const refTag = kind === 'worldinfo' ? 'worldinfo-reference ' : (kind === 'history' ? 'context-reference ' : 'input-reference ');
            return pilotPfx + body + '\n<!-- ' + refTag + taRandomHexId() + ' -->';
        }
        if (mode === 'zhuyin') {
            const masked = taTransformOutsideTags(body, taMaskZhuyin);
            if (masked === body && kind) return str;
            const openTag = kind === 'worldinfo' ? '[注音标注·世界书]' : (kind === 'history' ? '[注音标注·上下文]' : '[注音遮蔽]');
            const closeTag = kind === 'worldinfo' ? '[/注音标注·世界书]' : (kind === 'history' ? '[/注音标注·上下文]' : '[/注音遮蔽]');
            const note = kind ? '' : ('\n' + TA_ZHUYIN_NOTE);
            return pilotPfx + openTag + '\n' + masked + '\n' + closeTag + note;
        }
        if (mode === 'pinyin') {
            const py = taTransformOutsideTags(body, taToPinyin);
            const openTag = kind === 'worldinfo' ? '[PINYIN WORLD INFO]' : (kind === 'history' ? '[PINYIN CONTEXT]' : '[PINYIN INPUT]');
            const closeTag = kind === 'worldinfo' ? '[/PINYIN WORLD INFO]' : (kind === 'history' ? '[/PINYIN CONTEXT]' : '[/PINYIN INPUT]');
            const note = kind
                ? ''
                : '\nInterpret the phonetic Chinese input using context. Proper names and polyphonic characters may be ambiguous; do not invent certainty. Respond using the normal story format.';
            return pilotPfx + openTag + '\n' + py + '\n' + closeTag + note;
        }
        if (mode === 'base64') {
            const b64 = taUtf8Base64(body);
            const note = kind === 'worldinfo'
                ? '\nDecode this UTF-8 Base64 as active worldbook/lore context (preserving embedded tags and variable paths) and never print the decoding process.'
                : (kind === 'history'
                    ? '\nDecode this UTF-8 Base64 as historical context and never print the decoding process.'
                    : '\nDecode this UTF-8 Base64 as the current user input and respond in the normal format. Do not print the decoding process.');
            return pilotPfx + '[BASE64 UTF-8]\n' + b64 + '\n[/BASE64 UTF-8]' + note;
        }
        if (mode === 'gateway_hyphen') {
            return pilotPfx + maskNSFWTokensSafe(body, { structuredSafe: true });
        }
        return str;
    }

    function applyTransAmInputTransform(messages, floor, mode, includeContext = false, isStory = true, includeWorldInfo = false) {
        const result = { index: -1, method: 'transam-' + mode, reason: '', messages: 0, occurrences: 0, floorIndex: floor?.index ?? -1 };
        if (!Array.isArray(messages) || !messages.length) return result;

        // 兼容 TRANS-AM 一键大总结 JSON 请求体转换
        const sysSummaryMsg = messages.find(m => m && m.role === 'system' && typeof m.content === 'string' && m.content.startsWith('[TRANS-AM BIG SUMMARY REQUEST]'));
        if (sysSummaryMsg) {
            const summaryNoteMap = {
                zhuyin: '\nTRANSCRIPT ENCODING NOTE: ' + TA_ZHUYIN_NOTE + '请将注音词还原为正常简体中文写入 JSON 归档，切勿在归档结果中保留注音符号。',
                pinyin: '\nTRANSCRIPT ENCODING NOTE: Floor texts inside [PINYIN TRANSCRIPT]...[/PINYIN TRANSCRIPT] are Romanized Chinese Pinyin. Reconstruct standard Simplified Chinese in the JSON archive.',
                base64: '\nTRANSCRIPT ENCODING NOTE: Floor texts inside [BASE64 UTF-8 TRANSCRIPT]...[/BASE64 UTF-8 TRANSCRIPT] are UTF-8 Base64 encoded. Decode and write clean Simplified Chinese in the JSON archive.',
                gateway_hyphen: '\nTRANSCRIPT ENCODING NOTE: Some sensitive words in transcript floors are split by a middle dot (·) or hyphen (-). Remove those separators and write normal words in the JSON archive.',
                light_ref: '',
            };
            const note = summaryNoteMap[mode] || '';
            if (note && !sysSummaryMsg.content.includes('TRANSCRIPT ENCODING NOTE:')) {
                sysSummaryMsg.content += note;
            }
            for (let i = 0; i < messages.length; i++) {
                const m = messages[i];
                if (!m || m.role !== 'user' || typeof m.content !== 'string') continue;
                try {
                    const parsed = JSON.parse(m.content);
                    if (parsed && Array.isArray(parsed.floors)) {
                        parsed.floors = parsed.floors.map(f => {
                            if (!f || typeof f.text !== 'string') return f;
                            const cleanFloor = unmaskNSFWTokens(f.text);
                            let nextTxt = f.text;
                            if (mode === 'zhuyin') nextTxt = taTransformOutsideTags(cleanFloor, taMaskZhuyin);
                            else if (mode === 'pinyin') nextTxt = '[PINYIN TRANSCRIPT]\n' + taTransformOutsideTags(cleanFloor, taToPinyin) + '\n[/PINYIN TRANSCRIPT]';
                            else if (mode === 'base64') nextTxt = '[BASE64 UTF-8 TRANSCRIPT]\n' + taUtf8Base64(cleanFloor) + '\n[/BASE64 UTF-8 TRANSCRIPT]';
                            else if (mode === 'gateway_hyphen') nextTxt = maskNSFWTokensSafe(cleanFloor, { structuredSafe: true });
                            else if (mode === 'light_ref') nextTxt = cleanFloor + '\n<!-- summary-reference ' + taRandomHexId() + ' -->';
                            return { ...f, text: nextTxt };
                        });
                        m.content = JSON.stringify(parsed);
                        result.messages += 1;
                        result.occurrences += 1;
                    }
                } catch (_) {}
            }
            return result;
        }

        // 1. 当轮用户输入精确匹配转换（同时匹配 Step 1 连字符分词后的变体）+ <latest_input> 兜底
        const source = typeof floor?.text === 'string' ? floor.text : '';
        const baseVars = source ? textVariants(source) : [];
        const variants = [];
        for (const v of baseVars) {
            if (!v) continue;
            variants.push(v);
            const maskedV = maskNSFWTokensSafe(v, { structuredSafe: true });
            if (maskedV && maskedV !== v) variants.push(maskedV);
        }
        let targetUserIdx = -1;
        for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            if (!msg || msg.role !== 'user') continue;
            let hit = false;
            const repFn = txt => {
                let val = String(txt ?? '');
                for (const cand of variants) {
                    if (!cand || !val.includes(cand)) continue;
                    const enc = taEncodeSingleBlock(cand, mode, false);
                    if (enc === cand) continue;
                    val = val.split(cand).join(enc);
                    hit = true;
                    result.occurrences += 1;
                    break;
                }
                return val;
            };
            if (variants.length) {
                if (typeof msg.content === 'string') msg.content = repFn(msg.content);
                else if (Array.isArray(msg.content)) msg.content = msg.content.map(p => isTextLike(p) ? { ...p, text: repFn(p.text) } : p);
            }
            if (hit) {
                targetUserIdx = i;
                result.index = i;
                result.messages += 1;
                break;
            }
        }

        if (result.occurrences === 0) {
            const wrapRx = /(<(?:latest_input|ta_latest_input|本轮用户输入)>\s*(?:<audit_check>[\s\S]*?<\/audit_check>\s*)?)([\s\S]*?)(<\/(?:latest_input|ta_latest_input|本轮用户输入)>)/gi;
            for (let i = messages.length - 1; i >= 0; i--) {
                const msg = messages[i];
                if (!msg || msg.role !== 'user') continue;
                let hit = false;
                const wrapFn = s => String(s ?? '').replace(wrapRx, (whole, open, inner, close) => {
                    if (!inner || !inner.trim()) return whole;
                    const enc = taEncodeSingleBlock(inner, mode, false);
                    if (enc === inner) return whole;
                    hit = true;
                    result.occurrences += 1;
                    return open + enc + close;
                });
                if (typeof msg.content === 'string') msg.content = wrapFn(msg.content);
                else if (Array.isArray(msg.content)) msg.content = msg.content.map(p => isTextLike(p) ? { ...p, text: wrapFn(p.text) } : p);
                if (hit) {
                    targetUserIdx = i;
                    result.index = i;
                    result.method = 'input-tag-fallback-' + mode;
                    result.messages += 1;
                    break;
                }
            }
        }

        // 若为非正文脚本请求且无 <latest_input>，对最后一条 user 消息直接执行转换
        if (result.occurrences === 0 && !isStory) {
            for (let i = messages.length - 1; i >= 0; i--) {
                const msg = messages[i];
                if (!msg || msg.role !== 'user' || typeof msg.content !== 'string' || !msg.content.trim()) continue;
                msg.content = taEncodeSingleBlock(msg.content, mode, false);
                targetUserIdx = i;
                result.index = i;
                result.messages += 1;
                result.occurrences += 1;
                break;
            }
        }

        const wiMsgIndices = new Set();
        for (let i = 0; i < messages.length; i++) {
            if (isStandaloneWorldInfoMsg(messages[i])) wiMsgIndices.add(i);
        }
        const wiBlocks = collectActiveWorldInfoBlocks(messages);
        const wiExactTexts = new Set();
        for (const blk of wiBlocks) {
            for (const v of textVariants(blk)) {
                if (!v) continue;
                wiExactTexts.add(v);
                const mv = maskNSFWTokensSafe(v, { structuredSafe: true });
                if (mv) wiExactTexts.add(mv);
            }
        }
        const encodedMsgIndices = new Set();
        if (targetUserIdx >= 0) encodedMsgIndices.add(targetUserIdx);

        // 2. 可选：连带历史楼层编码（跳过 system 预设规则、世界书消息、工具消息与稀释垫片）
        let contextNoteAdded = false;
        if (includeContext) {
            for (let i = 0; i < messages.length; i++) {
                if (encodedMsgIndices.has(i) || wiMsgIndices.has(i)) continue;
                const m = messages[i];
                if (!m || (m.role !== 'user' && m.role !== 'assistant') || m.tool_calls || m.function_call) continue;
                if (typeof m.content !== 'string' || !m.content.trim()) continue;
                if (m.content.includes('<inert_lexical_entropy_buffer') || m.content.includes('<ta_rule_')) continue;
                if (wiExactTexts.has(m.content.trim()) || wiExactTexts.has(m.content)) continue;
                const next = taEncodeSingleBlock(m.content, mode, 'history');
                if (next !== m.content) {
                    m.content = next;
                    encodedMsgIndices.add(i);
                    result.messages += 1;
                    contextNoteAdded = true;
                }
            }
        }

        // 3. 可选：同步编码激活的世界书（独立世界书消息 + Squash 合并系统消息中的世界书块，绝对保护 <ta_rule_*>）
        if (includeWorldInfo) {
            for (const i of wiMsgIndices) {
                if (encodedMsgIndices.has(i)) continue;
                const m = messages[i];
                if (!m || typeof m.content !== 'string' || !m.content.trim()) continue;
                const next = taEncodeSingleBlock(m.content, mode, 'worldinfo');
                if (next !== m.content) {
                    m.content = next;
                    encodedMsgIndices.add(i);
                    result.messages += 1;
                    contextNoteAdded = true;
                }
            }
            if (wiBlocks.length > 0) {
                const wiVariants = [];
                const seenVar = new Set();
                for (const blk of wiBlocks) {
                    for (const v of textVariants(blk)) {
                        if (!v) continue;
                        if (!seenVar.has(v)) { seenVar.add(v); wiVariants.push(v); }
                        const mv = maskNSFWTokensSafe(v, { structuredSafe: true });
                        if (mv && mv !== v && !seenVar.has(mv)) { seenVar.add(mv); wiVariants.push(mv); }
                    }
                }
                wiVariants.sort((a, b) => b.length - a.length);
                const encodeSquashedOutsideRules = rawStr => {
                    if (typeof rawStr !== 'string' || !rawStr.trim()) return rawStr;
                    const parts = rawStr.split(/(<ta_rule_[a-z0-9_:-]*\b[^>]*>[\s\S]*?<\/ta_rule_[a-z0-9_:-]*>)/gi);
                    let touched = false;
                    for (let pIdx = 0; pIdx < parts.length; pIdx += 2) {
                        let seg = parts[pIdx];
                        if (!seg) continue;
                        if (seg.includes('[注音标注·世界书]') || seg.includes('[PINYIN WORLD INFO]') || seg.includes('[BASE64 UTF-8]') || seg.includes('worldinfo-reference ')) continue;
                        const placeholders = [];
                        for (const cand of wiVariants) {
                            if (!cand || !seg.includes(cand)) continue;
                            const enc = taEncodeSingleBlock(cand, mode, 'worldinfo');
                            if (enc && enc !== cand) {
                                const token = `\0TA_WI_ENC_${placeholders.length}\0`;
                                placeholders.push(enc);
                                seg = seg.split(cand).join(token);
                                touched = true;
                            }
                        }
                        for (let phIdx = 0; phIdx < placeholders.length; phIdx++) {
                            seg = seg.split(`\0TA_WI_ENC_${phIdx}\0`).join(placeholders[phIdx]);
                        }
                        if (placeholders.length === 0 && rawStr.includes('<ta_rule_')) {
                            const hdrMatch = seg.match(/^((?:\s*(?:SPECIAL INSTRUCTION:[^\r\n]+|\[Session-ID:[^\]]+\])\s*\r?\n?)+)/);
                            const hdrPrefix = hdrMatch ? hdrMatch[1] : '';
                            const restSeg = hdrPrefix ? seg.slice(hdrPrefix.length) : seg;
                            if (restSeg.trim().length >= 20 && restSeg.trim() !== '[Start a new Chat]') {
                                const encSeg = taEncodeSingleBlock(restSeg, mode, 'worldinfo');
                                if (encSeg && encSeg !== restSeg) {
                                    seg = hdrPrefix + encSeg;
                                    touched = true;
                                }
                            }
                        }
                        parts[pIdx] = seg;
                    }
                    return touched ? parts.join('') : rawStr;
                };
                for (let i = 0; i < messages.length; i++) {
                    if (encodedMsgIndices.has(i) || wiMsgIndices.has(i)) continue;
                    const m = messages[i];
                    if (!m || (m.role !== 'system' && m.role !== 'user' && m.role !== 'assistant')) continue;
                    const rawTxt = typeof m.content === 'string' ? m.content : '';
                    if (m.role === 'system' && rawTxt && !rawTxt.includes('<ta_rule_') && !rawTxt.includes('[TA_NATIVE_DELIVERY]') && !rawTxt.includes('<inert_lexical_entropy_buffer') && !rawTxt.includes('<ta_roll_pool>') && !rawTxt.includes('<ta_custom_cot_slot>') && rawTxt.trim() !== '[Start a new Chat]' && rawTxt.trim().length >= 8) {
                        if (!rawTxt.includes('[注音标注·世界书]') && !rawTxt.includes('[PINYIN WORLD INFO]') && !rawTxt.includes('[BASE64 UTF-8]') && !rawTxt.includes('worldinfo-reference ')) {
                            const nextSys = taEncodeSingleBlock(rawTxt, mode, 'worldinfo');
                            if (nextSys !== rawTxt) {
                                m.content = nextSys;
                                encodedMsgIndices.add(i);
                                result.messages += 1;
                                contextNoteAdded = true;
                                continue;
                            }
                        }
                    }
                    let changed = false;
                    if (typeof m.content === 'string') {
                        const next = encodeSquashedOutsideRules(m.content);
                        if (next !== m.content) { m.content = next; changed = true; }
                    } else if (Array.isArray(m.content)) {
                        m.content = m.content.map(p => {
                            if (isTextLike(p)) {
                                const next = encodeSquashedOutsideRules(p.text);
                                if (next !== p.text) { changed = true; return { ...p, text: next }; }
                            }
                            return p;
                        });
                    }
                    if (changed) {
                        encodedMsgIndices.add(i);
                        result.messages += 1;
                        contextNoteAdded = true;
                    }
                }
            }
        }

        if (contextNoteAdded && mode === 'zhuyin') {
            for (let i = messages.length - 1; i >= 0; i--) {
                if (messages[i] && messages[i].role === 'user') {
                    appendToMsgContent(messages[i], '\n[Context Note: ' + TA_ZHUYIN_NOTE + ']', '注音符号书写的片段');
                    break;
                }
            }
        }
        return result;
    }

    // 裸 Unicode 转义安全还原（合并原脚本 7952735f，保护代码块/前端数据块/路径）
    const TA_BARE_UNICODE_PROTECTED_RX = /(<(script|style|pre|code|iframe|UpdateVariable|JSONPatch|ta_hub|tw_hub|div|details|svg)\b[^>]*>[\s\S]*?(?:<\/\2\s*>|$)|```[\s\S]*?(?:```|$)|~~~[\s\S]*?(?:~~~|$)|`[^`\r\n]*(?:`|$)|<[^>]*>|[A-Za-z]:\\[^\s<>"'`]+|\\\\[A-Za-z0-9_.-]+\\[^\s<>"'`]+)/gi;
    function taRestoreBareUnicodeEscapes(text) {
        if (typeof text !== 'string' || text.indexOf('\\u') === -1) return text;
        const trimmed = text.trimStart();
        if (trimmed.startsWith('{') || trimmed.startsWith('```')) return text;
        let result = '', cursor = 0;
        const decodeSeg = part => part.replace(/\\\\|\\u[dD][89aAbB][0-9a-f]{2}\\u[dD][c-fC-F][0-9a-f]{2}|\\u[0-9a-f]{4}/gi, token => {
            if (token === '\\\\') return token;
            const first = parseInt(token.slice(2, 6), 16);
            if (first < 128 || (token.length === 6 && first >= 0xd800 && first <= 0xdfff)) return token;
            return String.fromCharCode(first) + (token.length === 12 ? String.fromCharCode(parseInt(token.slice(8), 16)) : '');
        });
        for (const match of text.matchAll(TA_BARE_UNICODE_PROTECTED_RX)) {
            result += decodeSeg(text.slice(cursor, match.index)) + match[0];
            cursor = match.index + match[0].length;
        }
        return result + decodeSeg(text.slice(cursor));
    }

    async function repairLastAssistantBareUnicode(manual = true) {
        try {
            const stContext = parentWin.SillyTavern?.getContext?.() || globalThis.SillyTavern?.getContext?.();
            const chat = stContext?.chat;
            if (!Array.isArray(chat) || !chat.length) {
                if (manual) notify('warning', '当前无聊天记录可修复');
                return false;
            }
            let idx = -1;
            for (let i = chat.length - 1; i >= 0; i--) {
                if (chat[i] && !chat[i].is_user && !chat[i].is_system) { idx = i; break; }
            }
            if (idx < 0 || typeof chat[idx].mes !== 'string') {
                if (manual) notify('info', '未找到最近的助手回复');
                return false;
            }
            const raw = chat[idx].mes;
            const fixed = stripLeakedInjectedArtifacts(unmaskNSFWTokens(taRestoreBareUnicodeEscapes(raw)));
            if (fixed === raw) {
                if (manual) notify('info', '最近一条助手消息没有待还原的裸 Unicode / 注音 / 连字符残留');
                return false;
            }
            const setMsgs = resolveTavernHelperFn('setChatMessages');
            if (typeof setMsgs === 'function') {
                await setMsgs([{ message_id: idx, message: fixed }]);
            } else {
                chat[idx].mes = fixed;
                stContext?.updateMessageBlock?.(idx, chat[idx]);
                stContext?.saveChatDebounced?.();
            }
            if (manual) notify('success', '已还原并清洗最近一条助手消息');
            return true;
        } catch (err) {
            if (manual) notify('warning', '修复消息失败：' + (err?.message || String(err)));
            return false;
        }
    }

