    function unwrapTaRuleTagsInText(txt) {
        if (typeof txt !== 'string' || !txt || !/<\/?ta_rule_/i.test(txt)) return txt;
        const parts = txt.split(TA_OBFS_PROTECTED_RX);
        for (let i = 0; i < parts.length; i += 2) {
