            if (next !== txt) touched += 1;
            return next;
        };
        for (const m of messages) {
            if (!m) continue;
            if (typeof m.content === 'string') m.content = unwrapTxt(m.content);
            else if (Array.isArray(m.content)) {
                for (const p of m.content) {
                    if (p && p.type === 'text' && typeof p.text === 'string') p.text = unwrapTxt(p.text);
