    function evaluateTransAmCanaryStamp(rawStamp) {
        const cObj = runtime.canaryState;
        if (!cObj || !cObj.expected) return;
        const actual = String(rawStamp || '').trim().toUpperCase();
        if (!actual) return;
        const exp = cObj.expected.toUpperCase();
        const revOnly = (cObj.reversedOnly || '').toUpperCase();
        cObj.actual = actual;
        if (actual === exp) {
            cObj.state = 'ok';
            cObj.text = '🟢 路由验真：旗舰正常（首尾 ' + cObj.headSeed + '+' + cObj.tailSeed + ' → #' + exp + ' 命中）';
        } else {
            cObj.state = 'warn';
            if (actual.length === 4) {
                cObj.text = '🟡 路由验真：疑似降级/漏首锚（仅算4位 #' + actual + '，漏队首 #' + cObj.headSeed + '，期望 #' + exp + '）';
            } else if (revOnly && actual === revOnly) {
                cObj.text = '🟡 路由验真：疑似降级/漏变换（仅倒序 #' + actual + '，期望 #' + exp + '）';
            } else {
                cObj.text = '🟡 路由验真：疑似降级/心算偏差（回显 #' + actual + '，期望 #' + exp + '）';
            }
