    }

    function injectTransAmCanaryProbeInPlace(messages, useTool = false, options = {}) {
        if (!Array.isArray(messages) || !messages.length) return null;
        const passiveOnly = options?.passiveOnly === true;
        const LETTERS = 'ABCDEFGHJKLMNPQRSTUVWX', DIGITS = '12345678';
        const pick = s => s[Math.floor(Math.random() * s.length)];
        const headSeed = pick(LETTERS) + pick(DIGITS);
        const tailSeed = pick(LETTERS) + pick(DIGITS) + pick(LETTERS) + pick(DIGITS);
        const challenge = headSeed + tailSeed;
        const reversedOnly = challenge.split('').reverse().join('');
        const expected = reversedOnly.split('').map(taTransformCanaryChar).join('');

        for (const m of messages) {
            if (!m) continue;
            const stripOld = s => s.replace(/\[anchor-head:\s*[A-Z0-9]{2,8}\]\s*/gi, '').replace(/\n?\[Sync Check:[^\]]*\]/gi, '');
            if (typeof m.content === 'string') m.content = stripOld(m.content);
            else if (Array.isArray(m.content)) m.content.forEach(p => { if (p && typeof p.text === 'string') p.text = stripOld(p.text); });
        }

        const firstMsg = messages.find(m => m && (typeof m.content === 'string' || Array.isArray(m.content)));
        if (firstMsg) {
            const headTag = '[anchor-head: ' + headSeed + ']\n';
            if (typeof firstMsg.content === 'string') firstMsg.content = headTag + firstMsg.content;
            else if (Array.isArray(firstMsg.content)) {
                if (firstMsg.content[0] && typeof firstMsg.content[0].text === 'string') firstMsg.content[0].text = headTag + firstMsg.content[0].text;
