            const toolClause = useTool ? ' (inside ' + SYNTHETIC_TOOL_NAME + ' content string)' : '';
            const canaryNote = '\n[Sync Check: Combine the 2-char anchor-head from the first message with tail-seed "' + tailSeed + '" into a 6-char string, reverse all 6 chars, then shift each letter +1 (A->B) and replace each digit d with (9-d). Append ONLY "[ref: RESULT]" at the very end of your reply' + toolClause + ', with no explanation, no step-by-step calculation, and no heading.]';
