            state: 'pending',
            headSeed,
            tailSeed,
            reversedOnly,
            expected,
            actual: '',
            text: '🔵 路由验真：检测中（首尾 ' + headSeed + '+' + tailSeed + ' → 期望 #' + expected + '）…',
        };
        try { if (runtime.panel?.classList?.contains('visible')) syncConfigPanel(); } catch (_) {}
        return runtime.canaryState;
    }

    function taStripAndEvaluateCanary(text) {
