            .replace(/\r\n/g, '\n')
            .replace(/^\s*\[anchor-head:\s*[A-Z0-9]{2,8}\]\s*/i, '');
        const compact = taNormalizeOuterProbe(raw);
        if (!compact) return { status: 'matching_prefix', remainder: '' };
        if (TA_OUTER_COVER_COMPACT.startsWith(compact)) {
            return { status: compact === TA_OUTER_COVER_COMPACT ? 'exact_cover' : 'matching_prefix', remainder: '' };
        }
        const markerTail = '这句话是系统内部的证明，还是外部观察者留下的记录';
        const tailIdx = trimmed.indexOf(markerTail);
        if (tailIdx >= 0 && compact.startsWith(TA_OUTER_COVER_COMPACT.slice(0, 36))) {
            const after = trimmed.slice(tailIdx + markerTail.length).replace(/^[。.”"\s]+/, '');
            if (!after) return { status: 'exact_cover', remainder: '' };
            if (taIsTextualToolPrefix(after)) return { status: 'textual_tool_candidate', remainder: '' };
