        }
        const markerTail = '这句话是系统内部的证明，还是外部观察者留下的记录';
        const tailIdx = norm.indexOf(markerTail);
        if (tailIdx >= 0 && taNormalizeOuterProbe(norm.slice(0, tailIdx + markerTail.length)) === TA_OUTER_COVER_COMPACT) {
