            let rawCombined = taStripNoisePadBlocks(this.carry + chunkText);
            this.carry = '';
            // 暂存未闭合的 <ta_noise_pad> / <sec_xxxx_noise_pad> 块（上限 800 字符），实现流式 0 闪烁剥除
            const unclosedPadMatch = rawCombined.match(/\n?[ \t]*<(?:(?:ta|tw)|(?:cfg|sec|doc|blk|seg|note)_[a-z0-9]{4})_noise_pad\b[^>]*>[\s\S]*$/i);
