                if (!demoteSystem) {
                    injectHeaderAndSessionPrefix(normalized[0], plan);
                }

                bodyObj.messages = normalized;
            }
        }
    }

    // 7. 落盘兜底清洗器：确保即使跨 SSE 两个 delta 分片分别吐出 "肉-" 和 "棒"，
    //    在消息接收完成存入聊天历史前也会被 100% 抹平连字符，绝不污染历史楼层
    function sanitizeLatestChatMessageInPlace() {
        try {
            const stContext = parentWin.SillyTavern?.getContext?.();
            const chat = stContext?.chat;
            if (!Array.isArray(chat) || chat.length === 0) return;

            const lastMsg = chat[chat.length - 1];
            if (!lastMsg || lastMsg.is_user) return;

            let changed = false;
            if (typeof lastMsg.mes === 'string') {
                let baseMes = lastMsg.mes;
                const recFromPlain = taRecoverTextToolCall(baseMes);
                if (recFromPlain) baseMes = recFromPlain.content;
                else if (runtime.lastStoryRun?.outputMode === 'tool') baseMes = taStripOuterCoverText(baseMes);
                if (runtime.lastStoryRun && (runtime.lastStoryRun.salvaged || runtime.lastStoryRun.endedCleanly === false)) {
                    baseMes = taTrimUnclosedUpdateVariable(baseMes);
                }
                const cleanedMes = stripLeakedInjectedArtifacts(unmaskNSFWTokens(baseMes));
                if (cleanedMes !== lastMsg.mes) {
                    lastMsg.mes = cleanedMes;
                    changed = true;
                }
            }
            if (lastMsg.extra && typeof lastMsg.extra.reasoning === 'string') {
                const cleanedRsn = stripLeakedInjectedArtifacts(unmaskNSFWTokens(lastMsg.extra.reasoning), { stripBareThinking: false });
                if (cleanedRsn !== lastMsg.extra.reasoning) {
                    lastMsg.extra.reasoning = cleanedRsn;
                    changed = true;
                }
            }
            if (Array.isArray(lastMsg.swipes)) {
                for (let i = 0; i < lastMsg.swipes.length; i++) {
                    if (typeof lastMsg.swipes[i] === 'string') {
                        const cs = stripLeakedInjectedArtifacts(unmaskNSFWTokens(lastMsg.swipes[i]));
                        if (cs !== lastMsg.swipes[i]) {
                            lastMsg.swipes[i] = cs;
                            changed = true;
                        }
                    }
                }
            }
            if (changed) {
                if (typeof stContext.updateMessageBlock === 'function') {
                    try { stContext.updateMessageBlock(chat.length - 1, lastMsg); } catch (_) {}
                }
                if (typeof stContext.saveChatDebounced === 'function') {
                    stContext.saveChatDebounced();
                }
            }
        } catch (e) {}
    }


    function applyLegacyExternalPluginMode(target, legacyMode) {
