    function migrateSettings(saved) {
        if (!saved || typeof saved !== 'object') {
            return { migrated: true, settings: { ...DEFAULTS, settingsVersion: SETTINGS_VERSION } };
        }
        const savedVer = Number(saved.settingsVersion);
        if (savedVer >= SETTINGS_VERSION) {
            const next = {};
            for (const [key, spec] of Object.entries(SETTINGS_SCHEMA)) {
                next[key] = normalizeSchemaValue(spec, saved[key]);
            }
            next.settingsVersion = SETTINGS_VERSION;
            return { migrated: false, settings: next };
        }
        // 从 v4.7.7 (451) 升级：保留其余已配置开关，但对旧版 locked:true 强写的 sessionSaltEnabled 一次性复位为 false，后续尊重用户手动开关
        if (savedVer >= 451) {
            const next = {};
            for (const [key, spec] of Object.entries(SETTINGS_SCHEMA)) {
                next[key] = normalizeSchemaValue(spec, saved[key]);
            }
            next.sessionSaltEnabled = false;
            next.pluginSessionSalt = 'follow';
            if (typeof saved.cacheFirstMode !== 'boolean') next.cacheFirstMode = true;
            next.settingsVersion = SETTINGS_VERSION;
            return { migrated: true, settings: next };
        }

        // 更早旧版（settingsVersion < 451）按当前默认参数重置并保存
        return { migrated: true, settings: { ...DEFAULTS, settingsVersion: SETTINGS_VERSION } };
    }

    function loadSettings() {
        let shouldPersist = false;
        try {
            const raw = settingsStorage()?.getItem(SETTINGS_KEY);
            if (raw) {
                const saved = JSON.parse(raw);
                const res = migrateSettings(saved);
                runtime.settings = res.settings;
                shouldPersist = res.migrated;
            } else {
                runtime.settings = { ...DEFAULTS, settingsVersion: SETTINGS_VERSION };
                shouldPersist = true;
            }
        } catch (error) {
            console.warn('[' + SCRIPT_NAME + '] settings load failed', error);
            runtime.settings = { ...DEFAULTS, settingsVersion: SETTINGS_VERSION };
            shouldPersist = true;
        }
        normalizeModes();
        if (shouldPersist) {
            try {
                settingsStorage()?.setItem(SETTINGS_KEY, JSON.stringify({ ...runtime.settings }));
            } catch (_) {}
        }
    }

    function saveSettings() {
        normalizeModes();
        try {
            settingsStorage()?.setItem(SETTINGS_KEY, JSON.stringify({ ...runtime.settings }));
        } catch (error) {
            console.warn(`[${SCRIPT_NAME}] 设置保存失败`, error);
        }
    }

    function normalizeModes() {
        const normalized = {};
        for (const [key, spec] of Object.entries(SETTINGS_SCHEMA)) {
            normalized[key] = normalizeSchemaValue(spec, runtime.settings?.[key]);
        }
        if (!normalized.entryFloatingEnabled && !normalized.entryQrEnabled && !normalized.entryMenuEnabled) {
            normalized.entryFloatingEnabled = true;
        }
        if (!normalized.externalPluginEnabled && normalized.externalPluginOnly) {
