            if (applyMask) {
                rules.push('点隔保护：仅在 JSON 字符串值或摘要叙述中出现高敏直白生理与动作词汇时可使用「字·字」中圆点间隔格式（严禁修改任何 JSON 键名、op/path 命令、时间格式或 XML 标签名），客户端会在解析前自动无感还原。');
