        const body = firstBreak >= 0 ? text.slice(firstBreak + 1) : text.slice(3);
        const lastFence = body.lastIndexOf('```');
        return (lastFence >= 0 ? body.slice(0, lastFence) : body).trim();
    }

    function extractString(source, start) {
        let output = '';
        let escaped = false;
        for (let index = start; index < source.length; index += 1) {
            const ch = source[index];
            if (escaped) {
                escaped = false;
                if (ch === 'u' && /^[0-9a-fA-F]{4}$/.test(source.slice(index + 1, index + 5))) {
                    output += String.fromCharCode(Number.parseInt(source.slice(index + 1, index + 5), 16));
                    index += 4;
                } else output += simpleEscape(ch) ?? ch;
            } else if (ch === '\\') escaped = true;
            else if (ch === '"') {
                const rest = source.slice(index + 1).trimStart();
                if (!rest || rest.startsWith('}') || rest.startsWith(',')) return output;
                output += '"';
            } else output += ch;
        }
        return output;
    }

    function extractContent(value) {
        if (value && typeof value === 'object') return typeof value.content === 'string' ? value.content : '';
        const raw = stripFence(value);
        if (!raw) return '';
        try {
            const parsed = JSON.parse(raw);
            if (typeof parsed?.content === 'string') return parsed.content;
        } catch (_) {}
        const key = raw.indexOf('"content"');
        if (key < 0) return '';
        const colon = raw.indexOf(':', key + 9);
        if (colon < 0) return '';
        const quote = raw.indexOf('"', colon + 1);
        return quote < 0 ? '' : extractString(raw, quote + 1);
    }

    // 读取从起始引号后开始的 JSON 字符串值；允许未闭合截断并正确处理转义字符
    function readJsonStringLoose(source, startIndex) {
        let out = '';
        let i = startIndex;
        let closed = false;
        while (i < source.length) {
            const ch = source[i];
            if (ch === '\\') {
                if (i + 1 >= source.length) break;
                const nxt = source[i + 1];
                if (nxt === 'u') {
                    if (i + 6 > source.length) break;
                    const hex = source.slice(i + 2, i + 6);
                    if (/^[0-9a-fA-F]{4}$/.test(hex)) {
                        out += String.fromCharCode(parseInt(hex, 16));
                        i += 6;
                        continue;
                    }
                }
                const mapped = simpleEscape(nxt);
                out += mapped !== undefined ? mapped : nxt;
                i += 2;
                continue;
            }
            if (ch === '"') {
                closed = true;
                i += 1;
                break;
            }
            out += ch;
            i += 1;
        }
        return { value: out, endIndex: i, closed };
    }

    // 从残缺或完整的工具 arguments JSON 字符串中提取字段（支持单字段未闭合截断与多字段）
    function extractFieldsFromLooseArgsJson(argsJsonStr) {
        const raw = String(argsJsonStr || '');
        if (!raw) return null;
        try {
            const parsed = JSON.parse(raw);
            if (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) {
                const fields = {};
                for (const [k, v] of Object.entries(parsed)) {
                    if (typeof v === 'string' && v.length > 0) fields[k] = v;
                }
                if (Object.keys(fields).length) return fields;
            }
        } catch (_) {}
        const fields = {};
        const keyRx = /"([A-Za-z0-9_\-]+)"\s*:\s*"/g;
        let m;
        while ((m = keyRx.exec(raw)) !== null) {
            const key = m[1];
            const read = readJsonStringLoose(raw, keyRx.lastIndex);
            keyRx.lastIndex = read.endIndex;
            if (key === 'arguments' || key === 'type' || key === 'name' || key === 'index' || key === 'id') continue;
            if (read.value && read.value.trim()) {
                fields[key] = fields[key] ? (fields[key] + read.value) : read.value;
            }
            if (!read.closed) break;
        }
        return Object.keys(fields).length ? fields : null;
    }

    function pickBestTextFromFields(fields) {
        if (!fields || typeof fields !== 'object') return '';
        const preferred = ['content', 'game_content', 'response', 'text', 'output', 'body', 'reply', 'story', 'narrative'];
        for (const k of preferred) {
            if (typeof fields[k] === 'string' && fields[k].trim()) return fields[k];
        }
        const vals = Object.entries(fields)
            .filter(([k, v]) => typeof v === 'string' && v.trim() && !/^(?:think|thought|reasoning)/i.test(k))
            .map(([, v]) => v);
        if (vals.length) return vals.join('\n\n');
        return Object.values(fields).filter(v => typeof v === 'string' && v.trim()).join('\n\n');
    }

    // 统一残缺/完整原始响应抢救：支持多帧 SSE、假流式单帧行内截断、单 JSON 对象截断、OpenAI/Google/Anthropic、DSML/CatieCLI 及 TRANS-AM 外层掩护剥离
    function salvageIncompletePayload(rawText, toolHint = '') {
        const input = String(rawText || '').trim();
        if (!input) return null;

        let toolName = toolHint || '';
        const nameMatch = input.match(/"name"\s*:\s*"([A-Za-z0-9_.:/\-]+)"/);
        if (!toolName && nameMatch) toolName = nameMatch[1];

        let parsedPlain = '';
        let parsedReasoning = '';
        let parsedArgs = '';
        let parsedJsonCount = 0;
        let sawCleanEnd = false;
        const brokenSegments = [];

        const appendToolArgChunk = seg => {
            if (typeof seg !== 'string' || !seg) return;
            if (parsedArgs && seg.length >= parsedArgs.length && seg.startsWith(parsedArgs)) {
                parsedArgs = seg;
                return;
            }
            if (parsedArgs && parsedArgs.length >= 16 && seg.length >= 16 && parsedArgs.startsWith(seg)) {
                return;
            }
            parsedArgs += seg;
        };

        const appendPlainChunk = seg => {
            if (typeof seg !== 'string' || !seg) return;
            if (parsedPlain && parsedPlain.length >= 16 && seg.length >= parsedPlain.length && seg.startsWith(parsedPlain)) {
                parsedPlain = seg;
                return;
            }
            if (parsedPlain && parsedPlain.length >= 16 && seg.length >= 16 && parsedPlain.startsWith(seg)) {
                return;
            }
            parsedPlain += seg;
        };

        const consumeObject = obj => {
            if (!obj || typeof obj !== 'object') return;
            parsedJsonCount++;
            if (Array.isArray(obj.choices)) {
                for (const ch of obj.choices) {
                    if (ch?.finish_reason === 'stop' || ch?.finish_reason === 'tool_calls') sawCleanEnd = true;
                    const d = ch?.delta || ch?.message;
                    if (!d || typeof d !== 'object') continue;
                    if (typeof d.content === 'string' && d.content) parsedPlain += d.content;
                    if (typeof d.reasoning_content === 'string' && d.reasoning_content) parsedReasoning += d.reasoning_content;
                    if (typeof d.reasoning === 'string' && d.reasoning) parsedReasoning += d.reasoning;
                    if (Array.isArray(d.tool_calls)) {
                        for (const tc of d.tool_calls) {
                            if (tc?.function?.name && !toolName) toolName = tc.function.name;
                            if (typeof tc?.function?.arguments === 'string') appendToolArgChunk(tc.function.arguments);
                        }
                    }
                    if (d.function_call && typeof d.function_call.arguments === 'string') {
                        if (d.function_call.name && !toolName) toolName = d.function_call.name;
                        appendToolArgChunk(d.function_call.arguments);
                    }
                }
                return;
            }
            if (Array.isArray(obj.candidates)) {
                for (const cand of obj.candidates) {
                    if (cand?.finishReason === 'STOP') sawCleanEnd = true;
                    const parts = cand?.content?.parts;
                    if (!Array.isArray(parts)) continue;
                    for (const pt of parts) {
                        if (!pt || typeof pt !== 'object') continue;
                        if (pt.functionCall) {
                            if (pt.functionCall.name && !toolName) toolName = pt.functionCall.name;
                            if (typeof pt.functionCall.args === 'string') appendToolArgChunk(pt.functionCall.args);
                            else if (pt.functionCall.args && typeof pt.functionCall.args === 'object') {
                                const picked = pickBestTextFromFields(pt.functionCall.args);
                                if (picked) parsedPlain += picked;
                            }
                            if (Array.isArray(pt.functionCall.partialArgs)) {
                                for (const pa of pt.functionCall.partialArgs) {
                                    if (typeof pa?.stringValue === 'string') parsedPlain += pa.stringValue;
                                }
                            }
                        } else if (typeof pt.text === 'string' && pt.text) {
                            if (pt.thought === true) parsedReasoning += pt.text;
                            else parsedPlain += pt.text;
                        }
                    }
                }
                return;
            }
            if (obj.type === 'message_stop') sawCleanEnd = true;
            if (obj.type === 'content_block_delta' && obj.delta) {
                if (obj.delta.type === 'text_delta' && typeof obj.delta.text === 'string') parsedPlain += obj.delta.text;
                else if (obj.delta.type === 'thinking_delta' && typeof obj.delta.thinking === 'string') parsedReasoning += obj.delta.thinking;
                else if (obj.delta.type === 'input_json_delta' && typeof obj.delta.partial_json === 'string') appendToolArgChunk(obj.delta.partial_json);
            } else if (obj.type === 'content_block_start' && obj.content_block) {
                if (obj.content_block.type === 'text' && typeof obj.content_block.text === 'string') parsedPlain += obj.content_block.text;
                else if (obj.content_block.type === 'tool_use' && obj.content_block.input && typeof obj.content_block.input === 'object') {
                    const picked = pickBestTextFromFields(obj.content_block.input);
                    if (picked) parsedPlain += picked;
                }
            } else if (typeof obj.delta === 'string' && obj.type === 'response.output_text.delta') {
                parsedPlain += obj.delta;
            }
        };

        const lines = input.split(/\r?\n/);
        const hasDataPrefix = lines.some(l => l.startsWith('data:'));
        if (hasDataPrefix) {
            for (const ln of lines) {
                if (!ln.startsWith('data:')) continue;
                const payload = ln.slice(5).trim();
                if (!payload) continue;
                if (payload === '[DONE]') { sawCleanEnd = true; continue; }
                try {
                    consumeObject(JSON.parse(payload));
                } catch (_) {
                    brokenSegments.push(payload);
                }
            }
        } else {
            try {
                const whole = JSON.parse(input);
                if (Array.isArray(whole)) {
                    for (const item of whole) consumeObject(item);
                } else {
                    consumeObject(whole);
                }
            } catch (_) {
                brokenSegments.push(input);
            }
        }

        // 从残缺 JSON 段中用状态机抽取未闭合的 arguments / content / text（复走累积快照去重，避免多帧断流重复拼接）
        for (const seg of brokenSegments) {
            const argRx = /"arguments"\s*:\s*"/g;
            let am;
            while ((am = argRx.exec(seg)) !== null) {
                const res = readJsonStringLoose(seg, argRx.lastIndex);
                argRx.lastIndex = res.endIndex;
                if (res.value) appendToolArgChunk(res.value);
                if (!res.closed) break;
            }
            const txtRx = /"(content|text)"\s*:\s*"/g;
            let tm;
            while ((tm = txtRx.exec(seg)) !== null) {
                const objStart = seg.lastIndexOf('{', tm.index);
                const beforeCtx = seg.slice(objStart >= 0 ? objStart : Math.max(0, tm.index - 40), tm.index);
                const res = readJsonStringLoose(seg, txtRx.lastIndex);
                txtRx.lastIndex = res.endIndex;
                if (/"thought"\s*:\s*true/.test(beforeCtx)) {
                    if (res.value) parsedReasoning += res.value;
                } else if (res.value) {
                    appendPlainChunk(res.value);
                }
                if (!res.closed) break;
            }
        }

        const totalArgs = parsedArgs;
        let rescuedBody = '';
        let mode = 'content';
        let unwrapTools = false;
        if (totalArgs) {
            const fields = extractFieldsFromLooseArgsJson(totalArgs);
            if (fields) {
                rescuedBody = pickBestTextFromFields(fields);
                mode = 'tool_calls';
                if (parsedPlain) {
                    try { taStripAndEvaluateCanary(parsedPlain); } catch (_) {}
                }
            }
        }
        if (!rescuedBody || !rescuedBody.trim()) {
            const combinedPlain = parsedPlain;
            if (combinedPlain && combinedPlain.trim()) {
                rescuedBody = combinedPlain;
                mode = parsedJsonCount > 0 ? 'stream_content' : 'loose_content';
                unwrapTools = true;
            } else if (parsedReasoning && parsedReasoning.trim()) {
                const rescuedFromRsn = taRescueSwallowedStoryFromReasoning(parsedReasoning, true);
                if (rescuedFromRsn && rescuedFromRsn.trim()) {
                    rescuedBody = rescuedFromRsn;
                    mode = 'reasoning_fallback';
                    unwrapTools = true;
                }
            }
        }
        if (!rescuedBody || !rescuedBody.trim()) return null;

        const isPartial = !sawCleanEnd || brokenSegments.length > 0;
        const cleanBody = taFinalizeSalvagedText(rescuedBody, { partial: isPartial, unwrapTools });
        if (!cleanBody || !cleanBody.trim()) return null;
        return {
            text: cleanBody,
            mode,
            chars: cleanBody.length,
            toolName: toolName || null,
            partial: isPartial,
        };
    }

    function responseHeaders(response, type) {
        const headers = new Headers(response.headers);
        headers.delete('content-length');
        headers.delete('content-encoding');
        if (type) headers.set('content-type', type);
        return headers;
    }

    function copyResponse(response, body, type) {
        return new Response(body, {
            status: response.status,
            statusText: response.statusText,
            headers: responseHeaders(response, type),
        });
    }

    function normalizeChoiceMessage(choice) {
        if (choice?.message && typeof choice.message === 'object') return choice.message;
        if (!choice.message) choice.message = {};
        return choice.message;
    }

    function extractUnclosedPrefillPrefix(prefillTxt) {
        if (typeof prefillTxt !== 'string' || !prefillTxt.trim()) return { prefix: '', checkHead: '' };
        const trimmed = prefillTxt.trim();
        const openMatches = Array.from(trimmed.matchAll(/<([A-Za-z0-9_~\u4e00-\u9fa5-]+)(?:\s[^>]*)?>/g));
        for (let i = openMatches.length - 1; i >= 0; i--) {
            const fullTag = openMatches[i][0];
            const tagName = openMatches[i][1];
            if (!trimmed.includes('</' + tagName + '>')) {
                return { prefix: fullTag + '\n', checkHead: '<' + tagName };
            }
        }
        return { prefix: '', checkHead: '' };
    }

    function normalizeOpenAiResponse(parsed, toolName, trailingPrefillText = '', outerCoverActive = false) {
        let hit = false, chars = 0, conflict = false, integrity = true;
        const finishReasons = [];
        const unmaskEnabled = true;
        const processor = new ResponseStream(toolName, unmaskEnabled, trailingPrefillText);
        const pf = extractUnclosedPrefillPrefix(trailingPrefillText);
        if (parsed?.error) throw streamError('upstream_error');
        if (Array.isArray(parsed?.choices)) {
            for (const choice of parsed.choices) {
                const reason = choice.finish_reason;
                if (reason != null) finishReasons.push(String(reason)); else integrity = false;
                if (processor.cutShort(reason)) integrity = false;
                const message = normalizeChoiceMessage(choice);
                const calls = Array.isArray(message.tool_calls) && message.tool_calls.length
                    ? message.tool_calls
                    : (message.function_call ? [{ id: 'legacy_fc_0', type: 'function', function: message.function_call }] : []);
                const keep = [];
                let owned = false, recovered = '';
                for (const call of calls) {
                    if (!isOwnTool(call?.function?.name, toolName)) { keep.push(call); continue; }
                    hit = owned = true;
                    const reader = new ArgumentReader();
                    const chunkPart = reader.feed(call.function.arguments) + reader.finish(processor.cutShort(reason));
                    recovered = recovered ? (recovered + chunkPart) : chunkPart;
                    integrity &&= reader.valid;
                }
                if (!owned) {
                    if (typeof message.content === 'string' && message.content.trim() && keep.length === 0) {
                        const recTextTool = taRecoverTextToolCall(message.content);
                        if (recTextTool) {
                            hit = true;
                            if (recTextTool.partial) integrity = false;
                            let cleanedRec = unmaskEnabled ? stripLeakedInjectedArtifacts(unmaskNSFWTokens(recTextTool.content)) : recTextTool.content;
                            if (pf.checkHead) {
                                const pt = cleanedRec.trimStart();
                                if (pt && !pt.startsWith(pf.checkHead) && !pt.startsWith('<')) {
                                    cleanedRec = (unmaskEnabled ? unmaskNSFWTokens(pf.prefix) : pf.prefix) + cleanedRec;
                                }
                            }
                            message.content = cleanedRec;
                            message.role = 'assistant';
                            chars += message.content.length;
                            continue;
                        }
                        if (outerCoverActive) {
                            const strippedPlain = taStripOuterCoverText(message.content);
                            if (strippedPlain !== message.content) {
                                message.content = strippedPlain.trim()
                                    ? (unmaskEnabled ? stripLeakedInjectedArtifacts(unmaskNSFWTokens(strippedPlain)) : strippedPlain)
                                    : '';
                                if (!message.content) integrity = false;
                                chars += message.content.length;
                                continue;
                            }
                        }
                    }
                    const plainTxt = typeof message.content === 'string' ? message.content.trim() : '';
                    const rsnTxt = typeof message.reasoning_content === 'string' && message.reasoning_content.trim()
                        ? message.reasoning_content
                        : (typeof message.reasoning === 'string' ? message.reasoning : '');
                    if (!plainTxt && rsnTxt && rsnTxt.trim() && keep.length === 0) {
                        let rescuedRsn = taRescueSwallowedStoryFromReasoning(rsnTxt, unmaskEnabled);
                        if (rescuedRsn && rescuedRsn.trim()) {
                            if (pf.checkHead) {
                                const probeTrim = rescuedRsn.trimStart();
                                if (probeTrim && !probeTrim.startsWith(pf.checkHead) && !probeTrim.startsWith('<')) {
                                    const restoredPrefix = unmaskEnabled ? unmaskNSFWTokens(pf.prefix) : pf.prefix;
                                    rescuedRsn = restoredPrefix + rescuedRsn;
                                }
                            }
                            message.content = rescuedRsn;
                            message.role = 'assistant';
                            chars += message.content.length;
                        }
                    }
                    continue;
                }
                if (recovered) {
                    recovered = unmaskEnabled ? stripLeakedInjectedArtifacts(unmaskNSFWTokens(recovered)) : recovered;
                    if (pf.checkHead) {
                        const probeTrim = recovered.trimStart();
                        if (probeTrim && !probeTrim.startsWith(pf.checkHead) && !probeTrim.startsWith('<')) {
                            const restoredPrefix = unmaskEnabled ? unmaskNSFWTokens(pf.prefix) : pf.prefix;
                            recovered = restoredPrefix + recovered;
                        }
                    }
                }
                const plainRawOrig = typeof message.content === 'string' ? message.content : '';
                const plainRaw = outerCoverActive ? taStripOuterCoverText(plainRawOrig) : plainRawOrig;
                const hasSubstantialPlain = plainRaw.trim().length > 0;
                conflict ||= Boolean(hasSubstantialPlain && recovered);
                delete message.function_call;
                // 工具流解包出的 recovered 优先（防止反代返回 content: "\n" 空白符把几千字工具输出覆盖成空回）
                const chosenContent = recovered
                    ? recovered
                    : (hasSubstantialPlain ? (unmaskEnabled ? stripLeakedInjectedArtifacts(unmaskNSFWTokens(plainRaw)) : plainRaw) : '');
                message.content = chosenContent;
                message.role = 'assistant'; chars += message.content.length;
                if (keep.length) message.tool_calls = keep;
                else { delete message.tool_calls; if (reason === 'tool_calls') choice.finish_reason = 'stop'; }
            }
        }
        const documents = Array.isArray(parsed?.candidates) ? parsed
            : Array.isArray(parsed?.responseContent?.parts) ? { candidates: [{ content: parsed.responseContent, finishReason: parsed.finishReason }] } : null;
        if (documents) {
            processor.googlePayload(documents);
            hit ||= processor.hit; chars += processor.chars; conflict ||= processor.conflict;
            integrity &&= processor.integrity && [...processor.google.values()].every(state => state.finished);
            finishReasons.push(...processor.finishReasons);
            if (processor.hit && parsed.responseContent && parsed.choices?.[0]) {
                normalizeChoiceMessage(parsed.choices[0]).content = parsed.responseContent.parts
                    .filter(part => part?.thought !== true && typeof part?.text === 'string').map(part => part.text).join('');
            }
        }
        if (!Array.isArray(parsed?.choices) && !documents) throw streamError('unknown_completion_format');
        return { parsed, hit, chars, conflict, integrity, finishReasons };
    }

    class OpenAiChoiceState {
        constructor() {
            this.calls = new Map(); this.channel = ''; this.finished = false;
            this.nextReal = 0; this.meta = {}; this.reason = null;
            this.outerPlainBuf = ''; this.outerFlushed = false;
        }
    }

    class ResponseStream {
        constructor(toolName, unmaskEnabled = true, trailingPrefillText = '', outerCoverActive = false) {
            this.toolName = toolName; this.unmaskEnabled = Boolean(unmaskEnabled); this.outerCoverActive = Boolean(outerCoverActive);
            this.openAi = new Map(); this.google = new Map();
            this.anthropic = { calls: new Map(), channel: '', finished: false, reason: null };
            this.protocol = ''; this.hit = false; this.chars = 0; this.outputTokens = 0; this.conflict = false;
            this.done = false; this.integrity = true; this.finishReasons = [];
            this.contentUnmasker = new StreamingUnmasker(unmaskEnabled);
            this.reasoningUnmasker = new StreamingUnmasker(unmaskEnabled);
            this.reasoningAccum = '';
            this.emittedPlainText = '';
            const pf = extractUnclosedPrefillPrefix(trailingPrefillText);
            this.prefillPrefix = unmaskEnabled && pf.prefix ? unmaskNSFWTokens(pf.prefix) : pf.prefix;
            this.prefillCheckHead = pf.checkHead;
            this.prefillChecked = !pf.checkHead;
            this.prefillProbeBuf = '';
        }
        choose(state, channel, text) {
            if (!text) return '';
            if (!state.channel) state.channel = channel;
            else if (state.channel !== channel) {
                if (channel === 'tool') {
                    if (state.channel === 'plain' && this.emittedPlainText.trim()) {
                        this.conflict = true;
                    }
                    state.channel = 'tool';
                } else {
                    if (!text.trim()) return '';
                    this.conflict = true;
                    return '';
                }
            }
            let clean = this.contentUnmasker.feed(text);
            if (clean) this.emittedPlainText += clean;
            this.chars += text.length;
            this.outputTokens += estimateTextTokenCount(text);
            if (!this.prefillChecked && clean) {
                this.prefillProbeBuf += clean;
                const probeTrim = this.prefillProbeBuf.trimStart();
                if ((probeTrim.length > 0 && !probeTrim.startsWith('<')) || probeTrim.length >= this.prefillCheckHead.length || probeTrim.includes('>')) {
                    this.prefillChecked = true;
                    if (!probeTrim.startsWith(this.prefillCheckHead) && !probeTrim.startsWith('<')) {
                        clean = this.prefillPrefix + this.prefillProbeBuf;
                    } else {
                        clean = this.prefillProbeBuf;
                    }
                    this.prefillProbeBuf = '';
                } else {
                    return '';
                }
            }
            return clean;
        }
        flushUnmaskers(opts = null) {
            let contentTail = this.contentUnmasker.flush(opts);
            if (!this.prefillChecked && (this.prefillProbeBuf || contentTail)) {
                this.prefillChecked = true;
                const combined = this.prefillProbeBuf + contentTail;
                const probeTrim = combined.trimStart();
                contentTail = (probeTrim && !probeTrim.startsWith(this.prefillCheckHead) && !probeTrim.startsWith('<'))
                    ? (this.prefillPrefix + combined)
                    : combined;
                this.prefillProbeBuf = '';
            }
            return {
                content: contentTail,
                reasoning: this.reasoningUnmasker.flush(opts),
            };
        }
        feedBufferedPlain(state, chunkText) {
            if (!chunkText) return '';
            if (!this.toolName || state.outerFlushed) {
                if (state.channel === 'tool' && this.outerCoverActive) {
                    taStripAndEvaluateCanary(chunkText);
                    return '';
                }
                return this.choose(state, 'plain', chunkText);
            }
            if (state.channel === 'tool') {
                taStripAndEvaluateCanary(chunkText);
                return '';
            }
            state.outerPlainBuf += chunkText;
            const cls = taClassifyOuterCoverBuffer(state.outerPlainBuf, this.outerCoverActive);
            if (cls.status === 'matching_prefix' || cls.status === 'exact_cover' || cls.status === 'textual_tool_candidate') {
                return '';
            }
            state.outerFlushed = true;
            const buf = state.outerPlainBuf;
