            for (const ch of text) {
                if (!mode) {
                    if (/\s|\uFEFF/.test(ch)) continue;
                    mode = ch === '[' ? 'array' : ch === '{' ? 'json' : 'sse';
                    framing.format = mode;
                    if (mode === 'array') continue;
                }
                if (mode === 'sse') {
                    if (++eventSize > STREAM_LIMIT) throw streamError('event_too_large');
                    if (afterCR && ch === '\n') { afterCR = false; continue; }
                    afterCR = ch === '\r';
                    if (ch === '\r' || ch === '\n') {
                        if (line === '') {
                            if (lines.length) yield eventRecord();
                        } else lines.push(line);
                        line = '';
                    } else line += ch;
                    continue;
                }
                if (nesting.length === 0) {
                    if (/\s/.test(ch)) continue;
                    if (framing.closed) throw new SyntaxError('响应结束后存在额外 JSON 数据');
                    if (mode === 'array') {
                        if (arrayStep === 'comma') {
                            if (ch === ',') { arrayStep = 'next'; continue; }
                            if (ch === ']') { framing.closed = true; continue; }
                            throw new SyntaxError('响应数组元素之间缺少逗号');
                        }
                        if (ch === ']' && arrayStep === 'first') { framing.closed = true; continue; }
                    }
                    if (ch !== '{') throw new SyntaxError('生成响应元素应为 JSON 对象');
                    record = '{';
                    nesting.push('}');
                    continue;
                }
                record += ch;
                if (record.length > STREAM_LIMIT) throw streamError('event_too_large');
                if (nesting.length > 256) throw streamError('json_too_deep');
                if (quoted) {
                    if (escaped) escaped = false;
                    else if (ch === '\\') escaped = true;
                    else if (ch === '"') quoted = false;
                    continue;
                }
                if (ch === '"') quoted = true;
                else if (ch === '{') nesting.push('}');
                else if (ch === '[') nesting.push(']');
                else if (ch === '}' || ch === ']') {
                    if (nesting.pop() !== ch) throw new SyntaxError('响应 JSON 括号不匹配');
                    if (!nesting.length) {
                        JSON.parse(record); // Reject complete but malformed records, rather than hiding an error.
                        const data = record;
                        record = '';
                        if (mode === 'json') framing.closed = true;
                        else arrayStep = 'comma';
                        yield { data, fields: [] };
                    }
                }
            }
        };
        try {
            while (true) {
                const next = await source.read();
                if (next.done) {
                    eof = true;
                    yield* scan(utf8.decode());
                    break;
                }
                framing.onBytes?.(next.value.byteLength);
                yield* scan(utf8.decode(next.value, { stream: true }));
            }
            if (mode === 'sse' && line) {
                lines.push(line);
                line = '';
            }
            if (mode === 'sse' && lines.length) {
                const rawTail = lines.join('\n');
                const rec = eventRecord();
                if (rec.data === null || rec.data.trim() === '[DONE]') {
                    yield rec;
                } else {
                    let validTailJson = false;
                    try { JSON.parse(rec.data); validTailJson = true; } catch (_) {}
                    if (validTailJson) {
                        yield rec;
                    } else {
                        framing.tailRaw = rawTail;
                        framing.incompleteRecord = true;
                        throw streamError('incomplete_record');
                    }
                }
            }
            if (record.length > 0) {
                framing.tailRaw = record;
                framing.incompleteRecord = true;
                throw streamError('incomplete_record');
            }
            if (mode === 'array' && !framing.closed) throw streamError('incomplete_json_array');
        } finally {
            if (!eof) {
                if (mode === 'sse' && (line || lines.length)) {
                    const parts = line ? [...lines, line] : lines;
                    framing.tailRaw = parts.join('\n');
                    framing.incompleteRecord = true;
                } else if (record.length > 0) {
                    framing.tailRaw = record;
                    framing.incompleteRecord = true;
                }
                await source.cancel().catch(() => {});
            }
            source.releaseLock();
        }
    }

    // Adapters transform complete records; waiting/abort/metrics stay in the transport layer.
    function transformStreamResponse(response, toolName, run, trailingPrefillText = '', outerCoverActive = false) {
        const encoder = new TextEncoder();
        const unmaskEnabled = true;
        const processor = new ResponseStream(toolName, unmaskEnabled, trailingPrefillText, outerCoverActive);
        const framing = { format: '', closed: false, incompleteRecord: false, onBytes: size => run.bytes(size) };
        let cancelled = false;
        let carryingRecords = 0;

        const report = extra => run.finish({
            syntheticHit: processor.hit, recoveredChars: processor.chars,
            contentConflict: processor.conflict, endedCleanly: processor.done && processor.integrity,
            semanticChecked: true, streamed: true, progressive: carryingRecords > 1, carryingRecords,
            responseFormat: framing.format, protocol: processor.protocol, finishReasons: processor.finishReasons.slice(),
            ...extra,
        });
        const encodeEvent = (payloads, fields = []) => {
            if (!payloads.length) return fields.length ? encoder.encode(fields.join('\n') + '\n\n') : null;
            return encoder.encode(payloads.map(value => {
                const eventFields = processor.protocol === 'anthropic' && fields.some(field => field.startsWith('event:'))
                    ? fields.map(field => field.startsWith('event:') ? 'event: ' + JSON.parse(value).type : field) : fields;
                return [...eventFields, ...value.split('\n').map(line => 'data: ' + line)].join('\n') + '\n\n';
            }).join(''));
        };

        const produce = async function* () {
            try {
                for await (const record of responseRecords(response.body, framing)) {
                    if (cancelled) return;
                    run.record(record);
                    if (record.data) {
                        try { applyUsageToRun(run, JSON.parse(record.data)); } catch (_) {}
                    }
                    const before = processor.chars;
                    const beforeTok = processor.outputTokens;
                    let payloads;
                    try { payloads = record.data === null ? [] : processor.payload(record.data); }
                    catch (error) {
                        if (error?.code !== 'upstream_stream_error') throw error;
                        const bytes = encodeEvent([record.data], record.fields);
                        report({ endedCleanly: false, ...failureDetails(error) });
                        if (bytes) yield bytes;
                        return;
                    }
                    if (processor.chars > before) { carryingRecords++; run.content(processor.chars - before, processor.outputTokens - beforeTok); }
                    else if (processor.outputTokens > beforeTok) { run.addOutputTokens?.(processor.outputTokens - beforeTok); }
                    run.update({ syntheticHit: processor.hit, contentConflict: processor.conflict });
                    const bytes = encodeEvent(payloads, record.fields);
                    if (bytes) yield bytes;
                    if (processor.done) {
                        processor.pending();
                        report({ connectionCompleted: true });
                        if (processor.finishReasons.some(r => processor.cutShort(r))) {
                            notify('warning', '检测到截断信号 (' + processor.finishReasons.join(',') + ')，已保留已生成正文');
                        }
                        taRestoreHostAutoContinueSoon();
                        setTimeout(sanitizeLatestChatMessageInPlace, 80);
                        return;
                    }
                }
            } catch (streamErr) {
                if (!cancelled && !processor.done) {
                    const tailSalvaged = framing.tailRaw ? salvageIncompletePayload(framing.tailRaw, toolName) : null;
                    if (processor.chars === 0 && tailSalvaged && tailSalvaged.text) {
                        console.warn('[' + SCRIPT_NAME + '] 单帧/断行残缺流抢救成功:', tailSalvaged.chars, streamErr);
                        const bodyText = tailSalvaged.text;
                        const proto = processor.protocol || (framing.tailRaw.includes('"candidates"') ? 'google' : (framing.tailRaw.includes('"content_block') ? 'anthropic' : 'openai'));
                        let enc = null;
                        if (proto === 'google') {
                            enc = encodeEvent([JSON.stringify({ candidates: [{ index: 0, content: { role: 'model', parts: [{ text: bodyText }] }, finishReason: 'STOP' }] })]);
                        } else if (proto === 'anthropic') {
                            enc = encodeEvent([
                                JSON.stringify({ type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: bodyText } }),
                                JSON.stringify({ type: 'message_delta', delta: { stop_reason: 'end_turn' } }),
                                JSON.stringify({ type: 'message_stop' }),
                            ]);
                        } else {
                            const id = 'chatcmpl-salvage-' + Date.now().toString(36);
                            enc = encodeEvent([
                                JSON.stringify({ id, object: 'chat.completion.chunk', choices: [{ index: 0, delta: { role: 'assistant', content: bodyText }, finish_reason: null }] }),
                                JSON.stringify({ id, object: 'chat.completion.chunk', choices: [{ index: 0, delta: {}, finish_reason: 'stop' }] }),
                                '[DONE]',
                            ]);
                        }
                        if (enc) yield enc;
                        processor.chars += bodyText.length;
                        processor.outputTokens += estimateTextTokenCount(bodyText);
                        processor.done = true;
                        run.content(bodyText.length, estimateTextTokenCount(bodyText));
                        report({ endedCleanly: false, salvaged: true, ...failureDetails(streamErr) });
                        notify('warning', '上游流中途断开，已为您抢救保住 ' + bodyText.length + ' 字内容');
                        taRestoreHostAutoContinueSoon();
                        setTimeout(sanitizeLatestChatMessageInPlace, 80);
                        return;
                    }
                    if (processor.chars > 0) {
                        console.warn('[' + SCRIPT_NAME + '] 流中途断开，启用半截无损抢救:', streamErr);
                        // 1) 若 tailRaw 为真实 OpenAI 增量 tool_calls 分片（仅含 arguments 续传而无 {"content": 键名），先续喂进已激活的 ArgumentReader
                        if ((!tailSalvaged || !tailSalvaged.text) && framing.tailRaw && processor.protocol === 'openai') {
                            const argKeyMatch = /"arguments"\s*:\s*"/i.exec(framing.tailRaw);
                            const fragParsed = argKeyMatch ? readJsonStringLoose(framing.tailRaw, argKeyMatch.index + argKeyMatch[0].length) : null;
                            const fragArgs = typeof fragParsed?.value === 'string' ? fragParsed.value : '';
                            if (fragArgs) {
                                for (const st of processor.openAi.values()) {
                                    for (const call of st.calls.values()) {
                                        if (call.kind === 'own' && call.reader) {
                                            const fed = call.reader.feed(fragArgs);
                                            if (fed) {
                                                const fedClean = processor.choose(st, 'tool', fed);
                                                if (fedClean) {
                                                    st._salvagedFedClean = (st._salvagedFedClean || '') + fedClean;
                                                }
                                            }
                                            break;
                                        }
                                    }
                                }
                            }
                        }
                        // 2) 先刷出 unmasker carry（断流时截除残缺末尾半个 \u 转义），再基于完整 emittedPlainText 计算 deltaTail，避免顺序错乱与 carry 重复
                        const flPre = processor.flushUnmaskers({ stripTrailingIncomplete: true });
                        if (flPre.content) processor.emittedPlainText += flPre.content;
                        let deltaTail = '';
                        if (tailSalvaged && tailSalvaged.text) {
                            const emitted = processor.emittedPlainText || '';
                            if (!emitted) {
                                deltaTail = tailSalvaged.text;
                            } else if (tailSalvaged.text.startsWith(emitted)) {
                                deltaTail = tailSalvaged.text.slice(emitted.length);
                            } else {
                                const tailProbe = emitted.slice(-Math.min(80, emitted.length));
                                const idx = tailProbe ? tailSalvaged.text.lastIndexOf(tailProbe) : -1;
                                if (idx >= 0) {
                                    deltaTail = tailSalvaged.text.slice(idx + tailProbe.length);
                                } else if (!emitted.endsWith(tailSalvaged.text)) {
                                    deltaTail = tailSalvaged.text;
                                }
                            }
                            deltaTail = taTrimUnclosedUpdateVariable(deltaTail);
                        }
                        let salvage = null;
                        if (processor.protocol === 'openai') {
                            const oaiFrames = [];
                            let preFed = '';
                            for (const st of processor.openAi.values()) {
                                if (st._salvagedFedClean) preFed += st._salvagedFedClean;
                            }
                            const combinedTail = preFed + taTrimUnclosedUpdateVariable(flPre.content || '') + deltaTail;
                            if (combinedTail) {
                                oaiFrames.push(JSON.stringify({
                                    id: 'chatcmpl-salvage-tail-' + Date.now().toString(36),
                                    object: 'chat.completion.chunk',
                                    choices: [{ index: 0, delta: { content: combinedTail }, finish_reason: null }],
                                }));
                            }
                            if (flPre.reasoning) {
                                oaiFrames.push(JSON.stringify({
                                    id: 'chatcmpl-salvage-rsn-' + Date.now().toString(36),
                                    object: 'chat.completion.chunk',
                                    choices: [{ index: 0, delta: { reasoning_content: flPre.reasoning }, finish_reason: null }],
                                }));
                            }
                            oaiFrames.push(JSON.stringify({
                                id: 'chatcmpl-salvage-end-' + Date.now().toString(36),
                                object: 'chat.completion.chunk',
                                choices: [{ index: 0, delta: {}, finish_reason: 'length' }],
                            }));
                            oaiFrames.push('[DONE]');
                            processor.done = true;
                            salvage = encodeEvent(oaiFrames);
                        } else if (processor.protocol === 'google') {
                            const fl = flPre;
                            const parts = [];
                            if (fl.reasoning) parts.push({ thought: true, text: fl.reasoning });
                            const googleTail = taTrimUnclosedUpdateVariable(flPre.content || '') + deltaTail;
                            if (googleTail) parts.push({ text: googleTail });
                            salvage = encodeEvent([JSON.stringify({ candidates: [{ index: 0, content: { role: 'model', parts }, finishReason: 'STOP' }] })]);
                            processor.done = true;
                        } else if (processor.protocol === 'anthropic') {
                            const fl = flPre;
                            const evs = [];
                            const anthTail = taTrimUnclosedUpdateVariable(flPre.content || '') + deltaTail;
                            if (anthTail) evs.push(JSON.stringify({ type: 'content_block_delta', index: 0, delta: { type: 'text_delta', text: anthTail } }));
                            evs.push(JSON.stringify({ type: 'message_delta', delta: { stop_reason: 'end_turn' } }));
                            evs.push(JSON.stringify({ type: 'message_stop' }));
                            salvage = encodeEvent(evs);
                            processor.done = true;
                        }
                        if (salvage) yield salvage;
                        report({ endedCleanly: false, salvaged: true, ...failureDetails(streamErr) });
                        notify('warning', '上游流中途断开，已为您无损保住已生成的 ' + processor.chars + ' 字内容');
                        taRestoreHostAutoContinueSoon();
                        setTimeout(sanitizeLatestChatMessageInPlace, 80);
                        return;
                    }
                }
                throw streamErr;
            }

            if (cancelled) return;
            if (framing.closed && processor.protocol === 'openai' && !processor.done) {
                const payloads = processor.payload('[DONE]');
                const encDone = encodeEvent(payloads);
                if (encDone) yield encDone;
            }
            const tail = encodeEvent(processor.pending());
            if (tail) yield tail;
            report({ connectionCompleted: true });
            taRestoreHostAutoContinueSoon();
                        setTimeout(sanitizeLatestChatMessageInPlace, 80);
        };
        const iterator = produce();
        const stream = new ReadableStream({
            async pull(controller) {
                try {
                    const next = await iterator.next();
                    if (cancelled) return;
                    if (next.done) controller.close();
                    else controller.enqueue(next.value);
                } catch (error) {
                    report({ endedCleanly: false, ...failureDetails(error) });
                    if (!cancelled) controller.error(error);
                }
            },
            async cancel(reason) {
                cancelled = true;
                try { if (framing.cancel) await framing.cancel(reason); else await response.body.cancel(reason); }
                finally {
                    await iterator.return();
                    if (processor.done || processor.chars > 0) {
                        report({ connectionCompleted: true, endedCleanly: true, cancelled: false });
                    } else {
                        report({ endedCleanly: false, cancelled: true });
                    }
                }
            },
        }, { highWaterMark: 0 });
        return new Response(stream, {
            status: response.status, statusText: response.statusText,
            headers: responseHeaders(response, 'text/event-stream; charset=utf-8'),
        });
    }

    // One outstanding read is retained across heartbeat ticks. No background enqueue loop.
    function observeStream(response, run, transformed, isSse = true) {
        const source = response.body.getReader();
        const heartbeat = new TextEncoder().encode(': anti-truncation local-wait\n\n');
        let pending = null, stopped = false, timer = null, controllerRef;
        const errorDecoder = !response.ok ? new TextDecoder() : null;
        let errorText = '';
        let boundary = true, lineHasBytes = false, afterCR = false;
        let lastByteAt = Date.now(), stallWarned = false;
        const boundaryScan = bytes => {
            for (const byte of bytes) {
                if (afterCR && byte === 10) { afterCR = false; continue; }
                afterCR = byte === 13;
                if (byte === 10 || byte === 13) { boundary = !lineHasBytes; lineHasBytes = false; }
                else { lineHasBytes = true; boundary = false; }
            }
        };
        const cleanup = () => {
            stopped = true; clearTimeout(timer); timer = null;
            run.signal.removeEventListener('abort', onAbort);
        };
        const onAbort = () => {
            if (stopped) return;
            cleanup();
            const reason = run.signal.reason || new DOMException('Aborted', 'AbortError');
            controllerRef.error(reason);
            void source.cancel(reason).catch(() => {});
        };
        const stream = new ReadableStream({
            start(controller) { controllerRef = controller; },
            async pull(controller) {
                if (stopped) return;
                try {
                    if (!pending) pending = source.read().then(next => ({ type: 'data', next }), error => ({ type: 'error', error }));
                    const nextRead = pending;
                    const result = isSse && run.localHeartbeat && (transformed || boundary || run.stats.upstreamBytes === 0)
                        ? await Promise.race([nextRead, new Promise(resolve => { timer = setTimeout(() => resolve({ type: 'heartbeat' }), STREAM_POLICY.heartbeatIntervalMs); })])
                        : await nextRead;
                    clearTimeout(timer); timer = null;
                    if (stopped) return;
                    if (result.type === 'heartbeat') {
                        if (!stallWarned && (Date.now() - lastByteAt) >= STREAM_POLICY.idleWarningMs) {
                            stallWarned = true;
                            notify('warning', '上游流超过 90 秒无响应，仍在保活等待中…');
                        }
                        run.update({ localHeartbeats: run.stats.localHeartbeats + 1 });
                        controller.enqueue(heartbeat); return;
                    }
                    pending = null;
                    if (result.type === 'error') throw result.error;
                    if (result.next.done) {
                        cleanup(); source.releaseLock();
                        if (!transformed) {
                            if (errorDecoder && errorText) {
                                let payload;
                                try { payload = JSON.parse(errorText + errorDecoder.decode()); }
                                catch { payload = { message: errorText }; }
                                const details = failureDetails(providerError(payload, 'HTTP ' + response.status));
                                run.update(details);
                            }
                            const resolvedEndedCleanly = run.stats.error
                                ? false
                                : (typeof run.stats.endedCleanly === 'boolean' ? run.stats.endedCleanly : (run.stats.recoveredChars > 0 ? true : null));
                            run.finish({ connectionCompleted: true, endedCleanly: resolvedEndedCleanly, semanticChecked: false, streamed: isSse });
                        }
                        controller.close(); return;
                    }
                    lastByteAt = Date.now();
                    if (!transformed) {
                        run.bytes(result.next.value.byteLength); boundaryScan(result.next.value);
                        if (errorDecoder && errorText.length < 4096) errorText = (errorText + errorDecoder.decode(result.next.value, { stream: true })).slice(0, 4096);
                    }
                    controller.enqueue(result.next.value);
                } catch (error) {
                    cleanup(); void source.cancel(error).catch(() => {});
                    run.finish({ endedCleanly: false, ...failureDetails(error) });
                    if (!run.signal.aborted) controller.error(error);
                }
            },
            async cancel(reason) {
                cleanup();
                try { await source.cancel(reason); }
                finally {
                    source.releaseLock();
                    if (run.stats.recoveredChars > 0) {
                        run.finish({ connectionCompleted: true, endedCleanly: true, cancelled: false });
                    } else {
                        run.finish({ endedCleanly: false, cancelled: true });
                    }
                }
            },
        }, { highWaterMark: 0 });
        run.signal.addEventListener('abort', onAbort, { once: true });
        if (run.signal.aborted) onAbort();
        return new Response(stream, {
            status: response.status, statusText: response.statusText, headers: responseHeaders(response),
        });
    }

    async function transformJsonResponse(response, toolName, run, trailingPrefillText = '', outerCoverActive = false) {
        // Bound the complete-response path as well as individual streaming records.
        const reader = response.body.getReader();
        const decoder = new TextDecoder('utf-8');
        let text = '', bytes = 0, eof = false;
        try {
            while (true) {
                const next = await reader.read();
                if (next.done) { eof = true; text += decoder.decode(); break; }
                bytes += next.value.byteLength; run.bytes(next.value.byteLength);
                if (bytes > STREAM_LIMIT) throw streamError('completion_too_large');
                text += decoder.decode(next.value, { stream: true });
            }
        } finally { if (!eof) await reader.cancel().catch(() => {}); reader.releaseLock(); }
        let parsed;
        try { parsed = JSON.parse(text); } catch { throw streamError('invalid_completion_json'); }
        if (parsed?.error || parsed?.type === 'error') {
            return {
                response: new Response(text, { status: response.status, statusText: response.statusText, headers: responseHeaders(response) }),
                stats: { endedCleanly: false, streamed: false, ...failureDetails(providerError(parsed, 'upstream_error')) },
            };
        }
        applyUsageToRun(run, parsed);
        const result = normalizeOpenAiResponse(parsed, toolName, trailingPrefillText, outerCoverActive);
        if (result.chars) run.content(result.chars);
        return {
            response: new Response(JSON.stringify(result.parsed), {
                status: response.status, statusText: response.statusText,
                headers: responseHeaders(response, 'application/json; charset=utf-8'),
            }),
            stats: { syntheticHit: result.hit, recoveredChars: result.chars, contentConflict: result.conflict,
                endedCleanly: result.integrity, semanticChecked: true, connectionCompleted: true,
                finishReasons: result.finishReasons, streamed: false, progressive: false },
        };
    }

    function createRun(prepared, args) {
        const id = ++runtime.runSerial;
        const started = Date.now();
        const controller = new AbortController();
        const inputSignal = args[1]?.signal ?? (args[0] instanceof Request ? args[0].signal : null);
        const stats = { id, time: started, phase: 'waiting-headers', ...prepared.summary,
            syntheticHit: false, recoveredChars: 0, estimatedOutputTokens: 0, contentConflict: false, endedCleanly: null,
            streamed: prepared.stream, headerMs: null, firstByteMs: null, firstContentMs: null,
            upstreamBytes: 0, upstreamRecords: 0, upstreamHeartbeats: 0, localHeartbeats: 0,
            lastByteMs: null, maxByteGapMs: 0, maxContentGapMs: 0, duration: 0, warning: '' };
        let finished = false, lastByte = started, lastContent = started, lastPublish = 0;
        const syncRunHistoryRecord = () => {
            const snap = { ...stats, finishReasons: stats.finishReasons?.slice() };
            const existingIdx = runtime.runHistory.findIndex(item => item && item.id === id);
            if (existingIdx >= 0) {
                runtime.runHistory[existingIdx] = snap;
            } else {
                runtime.runHistory.unshift(snap);
                if (runtime.runHistory.length > 30) runtime.runHistory.length = 30;
            }
            if (snap.requestTier === 'story' && (!runtime.lastStoryRun || runtime.lastStoryRun.id <= id)) {
                runtime.lastStoryRun = snap;
            }
            if (!runtime.lastRun || runtime.lastRun.id <= id || snap.requestTier === 'story' || runtime.lastRun.phase === 'streaming') {
                runtime.lastRun = snap;
            }
        };
        const publish = (force = false) => {
            if (runtime.disposed) return;
            const now = Date.now();
            if (!force && now - lastPublish < 600) return;
            lastPublish = now; stats.duration = now - started;
            syncRunHistoryRecord();
            syncConfigPanel();
        };
        const abortInput = () => run.abort(inputSignal.reason || new DOMException('Aborted', 'AbortError'));
        const interval = setInterval(() => {
            if (finished) return;
            const gap = Date.now() - lastByte;
            stats.idleByteMs = gap; stats.idleContentMs = Date.now() - lastContent;
            stats.warning = gap >= STREAM_POLICY.idleWarningMs
                ? (stats.headerMs === null ? '响应头尚未到达' : '上游字节静默') + ' ' + Math.floor(gap / 1000) + ' 秒'
                : stats.outputMode === 'tool' && stats.idleContentMs >= STREAM_POLICY.idleWarningMs
                    ? (stats.firstContentMs === null ? '上游有数据，正文尚未到达' : '上游有数据，正文暂未增加') + ' ' + Math.floor(stats.idleContentMs / 1000) + ' 秒' : '';
            publish(true);
        }, 1000);
        const run = {
            stats, signal: controller.signal, localHeartbeat: !prepared.summary?.bypassed && STREAM_POLICY.localHeartbeat,
            update(values) { if (!finished) { Object.assign(stats, values); publish(); } },
            headers(response) { stats.headerMs = Date.now() - started; stats.phase = 'waiting-body'; stats.httpStatus = response.status; publish(true); },
            bytes(size) {
                if (finished || !size) return;
                const now = Date.now(); stats.maxByteGapMs = Math.max(stats.maxByteGapMs, now - lastByte);
                lastByte = now; stats.lastByteMs = now - started; stats.firstByteMs ??= stats.lastByteMs;
                stats.upstreamBytes += size; stats.phase = 'streaming'; stats.warning = ''; publish();
            },
            record(record) { stats.upstreamRecords++; if (record.data === null) stats.upstreamHeartbeats++; },
            content(size, estTokens = null) {
                const now = Date.now(); stats.maxContentGapMs = Math.max(stats.maxContentGapMs, now - lastContent);
                lastContent = now; stats.firstContentMs ??= now - started; stats.recoveredChars += size;
                if (typeof estTokens === 'number' && estTokens > 0) stats.estimatedOutputTokens += estTokens;
                else if (typeof estTokens === 'string' && estTokens) stats.estimatedOutputTokens += estimateTextTokenCount(estTokens);
                else if (size > 0) stats.estimatedOutputTokens += Math.ceil(size * 0.9);
                publish();
            },
            addOutputTokens(tok) {
                if (finished || typeof tok !== 'number' || tok <= 0) return;
                stats.estimatedOutputTokens += tok;
                publish();
            },
            finish(values = {}) {
                if (finished) return;
                finished = true; clearInterval(interval); inputSignal?.removeEventListener('abort', abortInput);
                const now = Date.now();
                stats.duration = now - started;
                stats.idleByteMs = now - lastByte; stats.idleContentMs = now - lastContent;
                stats.maxByteGapMs = Math.max(stats.maxByteGapMs, now - lastByte);
                stats.maxContentGapMs = Math.max(stats.maxContentGapMs, now - lastContent);
                Object.assign(stats, { phase: values.cancelled ? 'cancelled' : values.error || stats.error ? 'error' : 'completed', warning: '' }, values);
                if (stats.outputMode === 'tool') {
                    const slow = STREAM_POLICY.idleWarningMs;
                    stats.waitAssessment = stats.headerMs === null ? '响应头前结束；需结合渠道日志定位等待点'
                        : stats.firstByteMs === null ? '响应头已到，响应体无字节；检查渠道等待与刷新'
                        : stats.firstContentMs === null ? '已有响应字节但无正文；检查工具参数缓冲与渠道错误'
                        : stats.progressive === false && stats.firstContentMs >= slow ? '长等待后集中返回正文；可能存在参数整包缓冲'
                        : stats.endedCleanly === false ? '已有正文后结束异常；检查结束原因与上游时限' : '';
                }
                runtime.activeRuns.delete(id); publish(true);
                if (stats.error && !stats.cancelled) {
                    console.warn(`[${SCRIPT_NAME}] 生成请求中断`, {
                        version: VERSION, durationMs: stats.duration, httpStatus: stats.httpStatus,
                        headerMs: stats.headerMs, firstByteMs: stats.firstByteMs, firstContentMs: stats.firstContentMs,
                        upstreamBytes: stats.upstreamBytes, upstreamRecords: stats.upstreamRecords,
                        recoveredChars: stats.recoveredChars, error: stats.error, errorMessage: stats.errorMessage,
                        upstreamError: stats.upstreamError, causeCode: stats.causeCode,
