                const key = String(prepared.request.chat_completion_source || 'custom') + ':' + String(prepared.request.model || 'unknown');
                runtime.capabilities.set(key, { channel: key, observedAt: now, protocol: stats.protocol || 'unobserved',
                    syntheticHit: stats.syntheticHit, progressive: stats.progressive ?? null,
                    firstByteMs: stats.firstByteMs, firstContentMs: stats.firstContentMs, endedCleanly: stats.endedCleanly,
                    error: stats.error || null });
                if (runtime.capabilities.size > 20) runtime.capabilities.delete(runtime.capabilities.keys().next().value);
