        inputSignal?.addEventListener('abort', abortInput, { once: true });
        if (inputSignal?.aborted) abortInput();
        publish(true);
        return run;
    }

    function formatRunTelemetryTag(run) {
        if (!run) return '';
        const tierTag = run.requestTier === 'story'
            ? '正文'
            : run.requestTier === 'baibai_query_rewrite'
                ? '柏宝书·向量'
                : String(run.requestTier || '').startsWith('baibai_memory')
                    ? '柏宝书·记忆'
                    : '插件';
        if (run.bypassed) {
            return `${tierTag} · 未处理（直连/放行）`;
        }
        const modeTag = run.outputMode === 'tool'
            ? (run.syntheticHit ? '工具流命中' : '工具流注入')
            : (run.maintenanceMode ? '原生·维护模式' : '普通流');
        const escMap = {
            json_escape: '整包转义',
            compact: '码点转义',
            hybrid_image: '转图片',
            full_armor: '深度破盾',
            zhuyin: '注音遮蔽',
            pinyin: '拼音转写',
            base64: 'Base64',
            gateway_hyphen: '实体破词',
            light_ref: '轻变换',
            off: '未转义',
        };
        const effInput = run.inputModeApplied || run.inputMode;
        const escTag = escMap[effInput] || '未转义';
        const charsTag = typeof run.recoveredChars === 'number' && run.recoveredChars > 0 ? ` · ${run.recoveredChars}字` : '';
        return `${tierTag} · ${modeTag} · ${escTag}${charsTag}`;
    }

    function pickBestDisplayRun() {
        const pluginOnly = isPluginOnlyBypassStoryMode();
        if (runtime.activeRuns.size > 0) {
            const activeList = Array.from(runtime.activeRuns.values()).map(r => r.stats);
            if (pluginOnly) {
                const activeNonBypassed = activeList.find(s => s && !s.bypassed);
                return activeNonBypassed || activeList[activeList.length - 1];
            }
            const activeStory = activeList.find(s => s && s.requestTier === 'story');
            return activeStory || activeList[activeList.length - 1];
        }
        if (pluginOnly) {
            const recentPlugin = runtime.runHistory.find(s => s && !s.bypassed);
            return recentPlugin || runtime.runHistory[0] || runtime.lastRun || null;
        }
        const recentStory = runtime.runHistory.find(s => s && s.requestTier === 'story');
        return recentStory || runtime.runHistory[0] || runtime.lastRun || null;
    }

    function runDescription(run) {
        const targetRun = pickBestDisplayRun() || run;
        if (!targetRun) {
            if (runtime.settings.pluginEnabled === false) return '💰 当前处于「计费省流直连模式」：额外 Token 消耗已归零';
            if (isPluginOnlyBypassStoryMode()) return '🧩 当前处于「只处理插件模式」：主聊天正文原样放行';
            const rLabel = ({ off: '关', clean: '轻度清洗', demote: '深度隔离' })[runtime.settings.routingLevel] || '轻度清洗';
            const jbOn = runtime.settings.jailbreakEnabled !== false;
            const extOn = runtime.settings.extraInjectionEnabled !== false;
            return `🛡 已就绪：防降智[${rLabel}] · 破甲[${jbOn ? '开' : '关'}] · 长文稀释[${extOn ? '开' : '关'}]（详情见「请求记录」）`;
        }
        const telemetry = formatRunTelemetryTag(targetRun);
        if (targetRun.bypassed) return `⏭ 已放行：${telemetry}`;
        if (targetRun.phase === 'cancelled' || targetRun.cancelled) return `⏹ 已手动停止（${telemetry}）`;
        if (targetRun.phase === 'error' || targetRun.error) return `⚠️ 中断：${targetRun.error || '请重试'}（${telemetry}）`;
        if (targetRun.phase === 'completed' || targetRun.connectionCompleted) {
            return targetRun.endedCleanly === false && !targetRun.recoveredChars
                ? `⚠️ 未完整接收（${telemetry}）`
                : `✅ 最新完成：${telemetry}`;
        }
        return (targetRun.firstContentMs == null ? '⏳ 等待首字… ' : '🟢 流式接收中… ') + `(${telemetry})`;
    }
