                        }
                        if (obj.type === 'content_block_delta' && obj.delta?.type === 'thinking_delta' && typeof obj.delta.thinking === 'string') {
                            try { run?.addOutputTokens?.(estimateTextTokenCount(obj.delta.thinking)); } catch (_) {}
                        }
                        emittedAnyFrame = true;
                        return 'data: ' + JSON.stringify(obj) + '\n\n';
                    }
                    return outSse;
                };

                const processHopLine = line => {
                    const trimmedLine = line.trim();
                    if (!trimmedLine) return '';
                    if (trimmedLine.startsWith(':')) return line + '\n\n';
                    if (trimmedLine.startsWith('event:') || trimmedLine.startsWith('id:') || trimmedLine.startsWith('retry:')) {
                        return line + '\n';
                    }
                    if (!line.startsWith('data:')) return '';
                    const rawPayload = line.slice(5).trimStart();
                    if (!rawPayload) return '';
                    if (rawPayload === '[DONE]') {
                        sawDone = true;
                        return '';
                    }
                    try {
                        const obj = JSON.parse(rawPayload);
                        return processPayloadObject(obj);
                    } catch (_) {
                        const rescued = salvageIncompletePayload(line, '');
                        if (rescued && rescued.text) {
                            return emitCleanContent(rescued.text, null);
                        }
                        return line + '\n\n';
                    }
                };

                let wireMode = '';
                let arrAt = 0;
                let arrStart = 0;
                let arrDepth = 0;
                let arrInElem = false;
                let arrInStr = false;
                let arrEsc = false;
                let arrOpened = false;

                const feedJsonArrayChunk = chunkStr => {
                    if (!chunkStr) return '';
                    arrBuf += chunkStr;
                    let out = '';
                    while (arrAt < arrBuf.length) {
                        const c = arrBuf[arrAt];
                        if (!arrInElem) {
                            if (!arrOpened) {
                                if (c === '[') { arrOpened = true; arrAt += 1; continue; }
                                if (c === ' ' || c === '\n' || c === '\r' || c === '\t') { arrAt += 1; continue; }
                                arrOpened = true;
                            }
                            if (c === ' ' || c === '\n' || c === '\r' || c === '\t' || c === ',') { arrAt += 1; continue; }
                            if (c === ']') { sawDone = true; arrAt += 1; continue; }
                            if (c === '{') {
                                arrInElem = true;
                                arrStart = arrAt;
                                arrDepth = 0;
                            } else {
                                arrAt += 1;
                                continue;
                            }
                        }
                        if (arrInStr) {
                            if (arrEsc) arrEsc = false;
                            else if (c === '\\') arrEsc = true;
                            else if (c === '"') arrInStr = false;
                        } else if (c === '"') {
                            arrInStr = true;
                        } else if (c === '{' || c === '[') {
                            arrDepth += 1;
                        } else if (c === '}' || c === ']') {
                            arrDepth -= 1;
                            if (arrDepth <= 0) {
                                const elemStr = arrBuf.slice(arrStart, arrAt + 1);
                                arrInElem = false;
                                arrBuf = arrBuf.slice(arrAt + 1);
                                arrAt = 0;
                                try {
                                    const elemObj = JSON.parse(elemStr);
                                    out += processPayloadObject(elemObj);
                                } catch (_) {}
                                continue;
                            }
                        }
                        arrAt += 1;
                    }
                    return out;
                };

                const feedText = textChunk => {
                    if (!textChunk) return '';
                    if (!wireMode) {
                        lineBuf += textChunk;
                        const probe = lineBuf.replace(/^[\s\uFEFF]+/, '');
                        if (!probe) return '';
                        if (probe[0] === '[') {
                            wireMode = 'json-array';
                            const initial = lineBuf;
                            lineBuf = '';
                            return feedJsonArrayChunk(initial);
                        }
                        if (probe[0] === '{') {
                            wireMode = 'json-obj';
                            return '';
                        }
                        wireMode = 'sse';
                    } else if (wireMode === 'json-array') {
                        return feedJsonArrayChunk(textChunk);
                    } else if (wireMode === 'json-obj') {
                        lineBuf += textChunk;
                        return '';
                    } else {
                        lineBuf += textChunk;
                    }
                    const lines = lineBuf.split('\n');
                    lineBuf = lines.pop() ?? '';
                    let batchOut = '';
                    for (const ln of lines) batchOut += processHopLine(ln);
                    return batchOut;
                };

                const reader = firstResponse.body.getReader();
                try {
                    while (true) {
                        const { done, value } = await reader.read();
                        if (done) break;
                        const batchOut = feedText(decoder.decode(value, { stream: true }));
                        if (batchOut) await writer.write(encoder.encode(batchOut));
                    }
                    const tailDecoded = decoder.decode();
                    if (tailDecoded) {
                        const tailOut = feedText(tailDecoded);
                        if (tailOut) await writer.write(encoder.encode(tailOut));
                    }
                    if (wireMode === 'json-obj' && lineBuf.trim()) {
                        try {
                            const singleObj = JSON.parse(lineBuf.trim());
                            const singleOut = processPayloadObject(singleObj);
                            if (singleOut) await writer.write(encoder.encode(singleOut));
                            sawDone = true;
                        } catch (_) {
                            const rescued = salvageIncompletePayload(lineBuf, '');
                            if (rescued && rescued.text) {
                                const salvOut = emitCleanContent(rescued.text, null);
                                if (salvOut) await writer.write(encoder.encode(salvOut));
                                sawDone = true;
                            }
                        }
                        lineBuf = '';
                    } else if (wireMode === 'sse' && lineBuf.trim()) {
                        const remOut = processHopLine(lineBuf);
                        if (remOut) await writer.write(encoder.encode(remOut));
                        lineBuf = '';
                    }

                    const remR = reasoningUnmasker.flush();
                    let remC = contentUnmasker.flush();
                    const isGoogleOut = seenGoogleProtocol || prepared?.isGoogleNative === true;
                    if (remR) {
                        if (reasoningAccum.length < 131072) reasoningAccum += remR;
                        emittedAnyFrame = true;
                        const rFrame = isGoogleOut
                            ? 'data: ' + JSON.stringify({ candidates: [{ index: 0, content: { role: 'model', parts: [{ thought: true, text: remR }] } }] }) + '\n\n'
                            : makeChunkLine({ reasoning_content: remR }, null);
                        await writer.write(encoder.encode(rFrame));
                    }
                    if (prefillRestorePending && (prefillProbeBuf || remC)) {
                        prefillRestorePending = false;
                        const combinedProbe = prefillProbeBuf + (remC || '');
                        prefillProbeBuf = '';
                        const probeTrim = combinedProbe.trimStart();
                        remC = (probeTrim && !probeTrim.startsWith(expectedPrefillHead) && !probeTrim.startsWith('<'))
                            ? (prefillPrefixStr + combinedProbe)
                            : combinedProbe;
                    }
                    if ((!remC || !remC.trim()) && totalNonWhitespaceChars === 0 && reasoningAccum.trim()) {
                        let rescued = taRescueSwallowedStoryFromReasoning(reasoningAccum, unmaskOn);
                        if (rescued && rescued.trim()) {
                            if (prefillAllowed && prefillPrefixStr && expectedPrefillHead) {
                                const probeTrim = rescued.trimStart();
                                if (probeTrim && !probeTrim.startsWith(expectedPrefillHead) && !probeTrim.startsWith('<')) {
                                    rescued = prefillPrefixStr + rescued;
                                }
                            }
                            remC = rescued;
                        }
                        reasoningAccum = '';
                    }
                    if (remC) {
                        totalEmittedChars += remC.length;
                        totalNonWhitespaceChars += remC.replace(/\s+/g, '').length;
                        try { run?.content?.(remC.length, remC); } catch (_) {}
                        emittedAnyFrame = true;
                        const cFrame = isGoogleOut
                            ? 'data: ' + JSON.stringify({ candidates: [{ index: 0, content: { role: 'model', parts: [{ text: remC }] } }] }) + '\n\n'
                            : makeChunkLine({ content: remC }, null);
                        await writer.write(encoder.encode(cFrame));
                    }
                } finally {
                    try { reader.releaseLock(); } catch (_) {}
                }

                const isGoogleOutEnd = seenGoogleProtocol || prepared?.isGoogleNative === true;
                let flushTail = '';
                if (!isGoogleOutEnd && (lastSeenFinishReason != null || (totalEmittedChars > 0 && wireMode !== 'sse'))) {
                    flushTail += makeChunkLine({}, lastSeenFinishReason || 'stop');
                }
                if (!isGoogleOutEnd && deferredOpenAiUsage && !forwardedOpenAiUsage) {
                    forwardedOpenAiUsage = true;
                    flushTail += 'data: ' + JSON.stringify({ id: 'chatcmpl-stream-guard', object: 'chat.completion.chunk', choices: [], usage: deferredOpenAiUsage }) + '\n\n';
                }
                if (sawDone || (!isGoogleOutEnd && (totalEmittedChars > 0 || emittedAnyFrame || flushTail))) {
                    flushTail += 'data: [DONE]\n\n';
                }
                if (flushTail) await writer.write(encoder.encode(flushTail));

                try {
                    if (run) {
                        const patch = {};
                        if (totalEmittedChars > 0) {
                            patch.endedCleanly = true;
                            patch.recoveredChars = totalEmittedChars;
                        }
                        if (recordedFinishReasons.length > 0) {
                            patch.finishReasons = recordedFinishReasons;
                        }
                        if (Object.keys(patch).length) run.update(patch);
                    }
                } catch (_) {}
                await writer.close();
                if (unmaskOn && prepared?.summary?.requestTier === 'story') {
                    taRestoreHostAutoContinueSoon();
                    setTimeout(sanitizeLatestChatMessageInPlace, 80);
                }
            } catch (err) {
                try {
                    const isGoogleOutErr = seenGoogleProtocol || prepared?.isGoogleNative === true;
                    const remC = contentUnmasker.flush();
                    let combinedTail = (prefillRestorePending ? (prefillProbeBuf + remC) : remC);
                    prefillRestorePending = false;
                    prefillProbeBuf = '';
                    const pendingRaw = (lineBuf || '') + (arrBuf || '');
                    if (pendingRaw.trim()) {
                        const rescued = salvageIncompletePayload(pendingRaw, '');
                        if (rescued && rescued.text) {
                            combinedTail += rescued.text;
                        }
                    }
                    if (combinedTail) {
                        combinedTail = taFinalizeSalvagedText(combinedTail, { partial: true, unwrapTools: false });
                    }
                    let salvagedTail = '';
                    if (combinedTail) {
                        totalEmittedChars += combinedTail.length;
                        totalNonWhitespaceChars += combinedTail.replace(/\s+/g, '').length;
                        try { run?.content?.(combinedTail.length, combinedTail); } catch (_) {}
                        salvagedTail += isGoogleOutErr
                            ? 'data: ' + JSON.stringify({ candidates: [{ index: 0, content: { role: 'model', parts: [{ text: combinedTail }] }, finishReason: 'STOP' }] }) + '\n\n'
                            : makeChunkLine({ content: combinedTail }, null);
                    }
                    if (totalEmittedChars > 0 || salvagedTail) {
                        if (!isGoogleOutErr) {
                            salvagedTail += makeChunkLine({}, lastSeenFinishReason || 'stop') + 'data: [DONE]\n\n';
                        }
                        if (salvagedTail) await writer.write(encoder.encode(salvagedTail));
                        try { run?.update?.({ endedCleanly: false, salvaged: true, recoveredChars: totalEmittedChars }); } catch (_) {}
                        await writer.close();
                        if (unmaskOn && prepared?.summary?.requestTier === 'story') {
                            taRestoreHostAutoContinueSoon();
                            setTimeout(sanitizeLatestChatMessageInPlace, 80);
                        }
                        return;
                    }
                } catch (_) {}
                try { await writer.abort(err); } catch (_) {}
            }
        })();

        return new Response(readable, {
            status: firstResponse.status,
            statusText: firstResponse.statusText,
            headers: responseHeaders(firstResponse, 'text/event-stream; charset=utf-8'),
        });
    }

    async function handleResilientPlainJsonResponse(firstResponse, run = null) {
        const unmaskOn = true;
        let rawText = '';
        try {
            rawText = await firstResponse.clone().text();
        } catch (_) {
            return firstResponse;
        }
        if (!rawText || !rawText.trim()) return firstResponse;
        try {
            const parsed = JSON.parse(rawText);
            if (parsed && typeof parsed === 'object') {
                if (parsed.error || parsed.promptFeedback?.blockReason) {
                    return firstResponse;
                }
                let recoveredChars = 0;
                const finishReasons = [];
                if (Array.isArray(parsed.choices)) {
                    for (const ch of parsed.choices) {
                        if (ch?.finish_reason && !finishReasons.includes(ch.finish_reason)) finishReasons.push(ch.finish_reason);
                        const msg = ch?.message;
                        if (msg && typeof msg === 'object') {
                            if (typeof msg.content === 'string') {
                                if (unmaskOn) msg.content = stripLeakedInjectedArtifacts(unmaskNSFWTokens(msg.content));
                                recoveredChars += msg.content.length;
                            }
                            if (typeof msg.reasoning_content === 'string' && unmaskOn) msg.reasoning_content = unmaskNSFWTokens(msg.reasoning_content);
                            if (typeof msg.reasoning === 'string' && unmaskOn) msg.reasoning = unmaskNSFWTokens(msg.reasoning);
                            if ((!msg.content || !String(msg.content).trim()) && (!Array.isArray(msg.tool_calls) || msg.tool_calls.length === 0)) {
                                let fallbackRsn = (typeof msg.reasoning_content === 'string' && msg.reasoning_content.trim())
                                    ? msg.reasoning_content
                                    : (typeof msg.reasoning === 'string' && msg.reasoning.trim() ? msg.reasoning : '');
                                if (!fallbackRsn && Array.isArray(msg.reasoning_details)) {
                                    const joinedRd = msg.reasoning_details
                                        .map(rd => (rd && typeof rd === 'object' ? (rd.text ?? rd.content ?? rd.summary ?? '') : ''))
                                        .filter(t => typeof t === 'string' && t.trim())
                                        .join('\n');
                                    if (joinedRd.trim()) fallbackRsn = joinedRd;
                                }
                                if (fallbackRsn) {
                                    const rescuedRsn = taRescueSwallowedStoryFromReasoning(fallbackRsn, unmaskOn);
                                    if (rescuedRsn && rescuedRsn.trim()) {
                                        msg.content = rescuedRsn;
                                        recoveredChars += msg.content.length;
                                    }
                                }
                            }
                            if (Array.isArray(msg.tool_calls) && msg.tool_calls.length > 0) {
                                for (const tc of msg.tool_calls) {
                                    if (tc?.function && typeof tc.function.arguments === 'string') {
                                        try {
                                            const argObj = JSON.parse(tc.function.arguments);
                                            if (typeof argObj?.content === 'string') {
                                                if (unmaskOn) argObj.content = stripLeakedInjectedArtifacts(unmaskNSFWTokens(argObj.content));
                                                recoveredChars += argObj.content.length;
                                                if (unmaskOn) tc.function.arguments = JSON.stringify(argObj);
                                            }
                                        } catch (_) {}
                                    }
                                }
                            }
                        }
                    }
                } else if (Array.isArray(parsed.candidates)) {
                    for (const cand of parsed.candidates) {
                        if (cand?.finishReason && !finishReasons.includes(cand.finishReason)) finishReasons.push(cand.finishReason);
                        const parts = cand?.content?.parts;
                        if (Array.isArray(parts)) {
                            let hasNonThoughtText = false;
                            const thoughtTexts = [];
                            for (const pt of parts) {
                                if (pt && typeof pt.text === 'string') {
                                    if (unmaskOn) pt.text = unmaskNSFWTokens(pt.text);
                                    if (pt.thought !== true && pt.text.trim()) {
                                        hasNonThoughtText = true;
                                        recoveredChars += pt.text.length;
                                    } else if (pt.thought === true && pt.text.trim()) {
                                        thoughtTexts.push(pt.text);
                                    }
                                }
                                if (pt?.functionCall?.args && typeof pt.functionCall.args.content === 'string') {
                                    if (unmaskOn) pt.functionCall.args.content = stripLeakedInjectedArtifacts(unmaskNSFWTokens(pt.functionCall.args.content));
                                    hasNonThoughtText = true;
                                    recoveredChars += pt.functionCall.args.content.length;
                                }
                            }
                            if (!hasNonThoughtText && thoughtTexts.length > 0 && !parts.some(p => p?.functionCall)) {
                                const rescuedText = taRescueSwallowedStoryFromReasoning(thoughtTexts.join('\n'), unmaskOn);
                                if (rescuedText && rescuedText.trim()) {
                                    parts.push({ text: rescuedText });
                                    recoveredChars += rescuedText.length;
                                }
                            }
                        }
                    }
                }
                try {
                    if (run) {
                        run.record({ data: parsed });
                        applyUsageToRun(run, parsed);
                        if (recoveredChars > 0) run.content(recoveredChars);
                        if (finishReasons.length > 0) run.update({ finishReasons });
                    }
                } catch (_) {}
                if (!unmaskOn) return firstResponse;
                return copyResponse(firstResponse, JSON.stringify(parsed), 'application/json; charset=utf-8');
            }
        } catch (_) {
            if (!unmaskOn) return firstResponse;
            return copyResponse(firstResponse, unmaskNSFWTokens(rawText), 'application/json; charset=utf-8');
        }
        return firstResponse;
    }

    function teeCacheResponse(response, meta = {}) {
        if (!response || !response.body || typeof response.body.getReader !== 'function') return response;
        const now = Date.now();
        // 进场即重置上一轮缓存，彻底杜绝新轮断流或 0 字节失败时「抢救上次」串轮回填旧正文
        runtime.lastRawStream = {
            at: now,
            url: String(meta.url || ''),
            toolName: meta.toolName || '',
            status: response.status,
            bytes: 0,
            complete: false,
            error: null,
            data: new Uint8Array(0),
        };
        let srcReader = null;
        try {
            srcReader = response.body.getReader();
        } catch (_) {
            return response;
        }
        const chunks = [];
        let total = 0;
        let committed = false;
        const commitCache = (readErr = null, release = true) => {
            if (committed) return;
            committed = true;
            if (release) {
                try { srcReader.releaseLock(); } catch (_) {}
            }
            if (total <= 0) {
                runtime.lastRawStream = {
                    at: now,
                    url: String(meta.url || ''),
                    toolName: meta.toolName || '',
                    status: response.status,
                    bytes: 0,
                    complete: false,
                    error: readErr ? String(readErr.message || readErr) : null,
                    data: new Uint8Array(0),
                };
                return;
            }
            try {
                const data = new Uint8Array(total);
                let offset = 0;
                for (const c of chunks) { data.set(c, offset); offset += c.byteLength; }
                let tailText = '';
                try { tailText = new TextDecoder('utf-8').decode(data.slice(Math.max(0, total - 4096))); } catch (_) {}
                runtime.lastRawStream = {
                    at: now,
                    url: String(meta.url || ''),
                    toolName: meta.toolName || '',
                    status: response.status,
                    bytes: total,
                    complete: tailText.includes('[DONE]') && !readErr,
                    error: readErr ? String(readErr.message || readErr) : null,
                    data,
                };
            } catch (_) {}
        };
        const passStream = new ReadableStream({
            async pull(controller) {
                try {
                    const { done, value } = await srcReader.read();
                    if (done) {
                        commitCache(null);
                        controller.close();
                        return;
                    }
                    if (value && value.byteLength && total < STREAM_LIMIT) {
                        const u8 = value instanceof Uint8Array
                            ? value
                            : (ArrayBuffer.isView(value) ? new Uint8Array(value.buffer, value.byteOffset, value.byteLength) : new Uint8Array(value));
                        const remain = STREAM_LIMIT - total;
                        const piece = u8.byteLength <= remain ? u8.slice() : u8.slice(0, remain);
                        chunks.push(piece);
                        total += piece.byteLength;
                    }
                    controller.enqueue(value);
                } catch (err) {
                    commitCache(err);
                    controller.error(err);
                }
            },
            async cancel(reason) {
                const cancelErr = reason !== undefined && reason !== null && String(reason) !== ''
                    ? new Error(String(reason))
                    : null;
                commitCache(cancelErr, false);
                try { await srcReader.cancel(reason); } catch (_) {}
                try { srcReader.releaseLock(); } catch (_) {}
            },
        });
        return new Response(passStream, {
            status: response.status,
            statusText: response.statusText,
            headers: new Headers(response.headers),
        });
    }

    async function salvageLastRawResponseIntoChat() {
        const rec = runtime.lastRawStream;
        if (!rec || !rec.bytes || !rec.data) {
            notify('warning', '暂无可抢救的响应缓存');
            return { ok: false, reason: 'no_cache' };
        }
        let rawText = '';
        try {
            rawText = new TextDecoder('utf-8').decode(rec.data);
        } catch (err) {
            notify('error', '缓存解码失败：' + (err?.message || String(err)));
            return { ok: false, reason: 'decode_failed' };
        }
        const rescued = salvageIncompletePayload(rawText, rec.toolName || '');
        if (!rescued || !rescued.text || !rescued.text.trim()) {
            notify('warning', '最近一次响应缓存中未提取到正文');
            return { ok: false, reason: 'empty_salvage' };
        }
        let stCtx = null;
        for (const host of hostWindows()) {
            try {
                const ctx = host?.SillyTavern?.getContext?.();
                if (ctx && Array.isArray(ctx.chat)) { stCtx = ctx; break; }
            } catch (_) {}
        }
        if (!stCtx) {
            notify('error', '未获取到酒馆聊天上下文，无法写入');
            return { ok: false, reason: 'no_context', text: rescued.text };
        }
        try {
            const lastIdx = stCtx.chat.length - 1;
            const lastMsg = lastIdx >= 0 ? stCtx.chat[lastIdx] : null;
            const isTailAssistant = Boolean(lastMsg && !lastMsg.is_user && !lastMsg.is_system);
            const curTrim = isTailAssistant ? String(lastMsg.mes || '').trim() : '';
            const resTrim = rescued.text.trim();
            if (
                isTailAssistant
                && curTrim
                && (
                    curTrim === resTrim
                    || (curTrim.length >= resTrim.length && (curTrim.includes(resTrim) || (resTrim.length >= 16 && curTrim.startsWith(resTrim.slice(0, 48)))))
                )
            ) {
                notify('info', '末楼已包含本次抢救正文，无需重复写入');
                return { ok: true, skipped: true, duplicate: true, chars: curTrim.length, mode: rescued.mode };
            }
            const canPatchTail = Boolean(
                isTailAssistant
                && (
                    !curTrim
                    || lastMsg.extra?.salvagedByTwintail === true
                    || (resTrim.length > curTrim.length && resTrim.startsWith(curTrim.slice(0, Math.min(24, curTrim.length))))
                )
            );
            if (canPatchTail) {
                lastMsg.mes = rescued.text;
                lastMsg.extra = { ...(lastMsg.extra || {}), salvagedByTwintail: true };
                if (typeof stCtx.updateMessageBlock === 'function') {
                    try { stCtx.updateMessageBlock(lastIdx, lastMsg); } catch (_) {}
                }
                if (typeof stCtx.saveChatDebounced === 'function') stCtx.saveChatDebounced();
                else if (typeof stCtx.saveChat === 'function') await stCtx.saveChat();
            } else {
                const message = {
                    name: stCtx.name2 || 'Assistant',
                    is_user: false,
                    is_system: false,
                    send_date: Date.now(),
                    mes: rescued.text,
                    extra: { salvagedByTwintail: true },
                };
                stCtx.chat.push(message);
                const newIdx = stCtx.chat.length - 1;
                if (typeof stCtx.addOneMessage === 'function') {
                    stCtx.addOneMessage(message, { scroll: true });
                } else if (typeof stCtx.reloadCurrentChat === 'function') {
                    await stCtx.reloadCurrentChat();
                }
                if (typeof stCtx.updateMessageBlock === 'function') {
                    try { stCtx.updateMessageBlock(newIdx, message); } catch (_) {}
                }
                if (typeof stCtx.saveChatDebounced === 'function') stCtx.saveChatDebounced();
                else if (typeof stCtx.saveChat === 'function') await stCtx.saveChat();
            }
            notify('success', `已抢救写入 ${rescued.text.length} 字`);
            return { ok: true, chars: rescued.text.length, mode: rescued.mode };
        } catch (err) {
            notify('error', '写入聊天失败：' + (err?.message || String(err)));
            return { ok: false, reason: 'write_failed', error: err?.message || String(err) };
        }
    }

    async function handleGeneration(original, thisArg, args) {
        const targetUrl = resolveUrl(args[0]);
        if (!interceptionEnabled()) {
            if (isSameOriginApiPath(targetUrl)) {
                const nextArgs = applySameOriginCsrfHeaders(targetUrl, args);
                return executeWithCsrfRetry(original, thisArg, nextArgs, targetUrl, null, nextArgs[1]?.signal || (isRequestLike(nextArgs[0]) ? nextArgs[0].signal : null));
            }
            return original.apply(thisArg, args);
        }
        const raw = await requestText(args);
        if (raw === null) {
            const nextArgs = applySameOriginCsrfHeaders(targetUrl, args);
            return executeWithCsrfRetry(original, thisArg, nextArgs, targetUrl, null, nextArgs[1]?.signal || (isRequestLike(nextArgs[0]) ? nextArgs[0].signal : null));
        }
        const prepared = prepareRequest(raw, targetUrl);
        if (prepared.kind === 'passthrough-clean') {
            const nextArgs = prepared.changed ? withBody(args, prepared.body) : applySameOriginCsrfHeaders(targetUrl, args);
            const replayBody = prepared.changed ? prepared.body : raw;
            if (!prepared.summary) {
