    function dispose(reason = 'manual') {
        if (runtime.disposed) return;
        runtime.disposed = true;
        for (const run of runtime.activeRuns.values()) run.abort('script-disposed');
        runtime.activeRuns.clear();
        removeFetch();
        clearPanelStops();
        runtime.lastFocusedElement = null;
        unmountFallbackLauncher();
        unmountQrButton();
        unmountMenuEntry();
        drainStops(runtime.uiStops);
        runtime.panel?.remove();
        runtime.style?.remove();
        runtime.launcher?.remove();
        const targets = [rootWindow(), ...hostWindows()];
        const seen = new Set();
        for (const host of targets) {
            if (!host || seen.has(host)) continue;
            seen.add(host);
            try {
                if (host[API_NAME]?.instanceId === INSTANCE_ID) {
                    try { delete host[API_NAME]; } catch (_) { host[API_NAME] = undefined; }
                }
                if (host[STATE_NAME]?.instanceId === INSTANCE_ID) {
                    try { delete host[STATE_NAME]; } catch (_) { host[STATE_NAME] = undefined; }
                }
                host[LOADED_FLAG] = false;
            } catch (_) {}
        }
        console.log(`[${SCRIPT_NAME}] 已卸载：${reason}`);
    }


    function cleanupLegacyAntiRouteResiduals() {
        try {
            const th = typeof TavernHelper !== 'undefined' ? TavernHelper : window.TavernHelper || parentWin.TavernHelper || {};
            const uninj = typeof uninjectPrompts === 'function' ? uninjectPrompts : th.uninjectPrompts;
            if (typeof uninj === 'function') {
                uninj(['g4a_top_prefix_bust', 'g4a_bottom_gate_lock', 'g4a_anti_route_header', 'g4a_anti_route_footer']);
            }
        } catch (_) {}
        try {
            const stContext = parentWin.SillyTavern?.getContext?.();
            const eventSource = stContext?.eventSource;
            const eventTypes = stContext?.event_types || {};
            if (eventSource) {
                const allEvs = [
                    eventTypes.CHAT_COMPLETION_SETTINGS_READY || 'chat_completion_settings_ready',
                    eventTypes.CHAT_COMPLETION_PROMPT_READY || 'chat_completion_prompt_ready',
                    eventTypes.MESSAGE_RECEIVED || 'message_received',
                    eventTypes.PRESET_CHANGED || 'preset_changed',
                    eventTypes.OAI_PRESET_CHANGED_AFTER || 'oai_preset_changed_after',
                ];
                for (const evName of allEvs) {
                    const bucket = eventSource?.events?.[evName] || eventSource?._events?.[evName];
                    if (Array.isArray(bucket)) {
                        for (let i = bucket.length - 1; i >= 0; i--) {
                            const s = String(bucket[i] || '');
                            if (
                                s.includes('__LAST_4A_') ||
                                s.includes('__G4A_') ||
                                s.includes('verifyTrue4ACompute') ||
                                s.includes('auditPhysicalTelemetry') ||
                                s.includes('buildFullSpectrumHighYaml') ||
                                s.includes('buildSilentHighYaml') ||
                                s.includes('healActiveIzumiPresetSilently')
                            ) {
                                bucket.splice(i, 1);
                            }
                        }
                    }
                }
            }
        } catch (_) {}
    }

    function runWhenHostCsrfReady(fn) {
        if (typeof fn !== 'function' || runtime.disposed) return;
        if (hasHostCsrfToken()) {
            fn();
            return;
        }
        let settled = false;
        let pollTimer = null;
        let tries = 0;
        let removeAppReadyListener = null;

        const cleanup = () => {
            if (pollTimer != null) {
                clearTimeout(pollTimer);
                pollTimer = null;
            }
            if (typeof removeAppReadyListener === 'function') {
                try { removeAppReadyListener(); } catch (_) {}
                removeAppReadyListener = null;
            }
        };

        const finish = () => {
            if (settled || runtime.disposed) return;
            settled = true;
            cleanup();
            try { fn(); } catch (_) {}
        };

        runtime.uiStops.push(cleanup);

        try {
            const stCtx = parentWin.SillyTavern?.getContext?.() || globalThis.SillyTavern?.getContext?.();
            const evSrc = stCtx?.eventSource;
            const appReadyEv = stCtx?.event_types?.APP_READY || stCtx?.eventTypes?.APP_READY || 'app_ready';
            if (evSrc && typeof evSrc.on === 'function' && appReadyEv) {
                const onAppReady = () => {
                    if (hasHostCsrfToken()) {
                        finish();
                    } else {
                        Promise.resolve(refreshCsrfToken()).finally(() => {
                            if (!runtime.disposed) finish();
                        });
                    }
                };
                evSrc.on(appReadyEv, onAppReady);
                removeAppReadyListener = () => {
                    try {
                        if (typeof evSrc.removeListener === 'function') evSrc.removeListener(appReadyEv, onAppReady);
                        else if (typeof evSrc.off === 'function') evSrc.off(appReadyEv, onAppReady);
                        else {
                            const bucket = evSrc.events?.[appReadyEv] || evSrc._events?.[appReadyEv];
                            if (Array.isArray(bucket)) {
                                const idx = bucket.indexOf(onAppReady);
                                if (idx !== -1) bucket.splice(idx, 1);
                            }
                        }
                    } catch (_) {}
                };
            }
        } catch (_) {}

        const tick = () => {
            if (settled || runtime.disposed) return;
            if (hasHostCsrfToken()) {
                finish();
                return;
            }
            if (tries >= 10) {
                Promise.resolve(refreshCsrfToken()).finally(() => {
                    if (!runtime.disposed) finish();
                });
                return;
            }
            tries += 1;
            pollTimer = setTimeout(tick, 300);
        };
        pollTimer = setTimeout(tick, 300);
    }

    function init() {
        const host = rootWindow(); const previous = host[API_NAME]; if (previous && previous.instanceId !== INSTANCE_ID) { try { previous.dispose?.('replaced'); } catch (_) {} }
        cleanupLegacyAntiRouteResiduals();
        loadSettings(); loadTextLibrary(); exposeApi(); syncFetchInstallation(); primeThGenerationTracker();
        syncLauncherAppearance();
        runWhenHostCsrfReady(() => {
            if (runtime.disposed) return;
            syncStPostProcessingForToolTransport();
            autoEnsureCompanionTavernRegex();
            try {
                const stCtx = parentWin.SillyTavern?.getContext?.();
                if (stCtx?.chatCompletionSettings && stCtx.chatCompletionSettings.stream_openai === false) {
                    stCtx.chatCompletionSettings.stream_openai = true;
                    const streamToggle = parentWin.document?.getElementById?.('stream_toggle');
                    const EvCtor = parentWin.Event || (typeof Event === 'function' ? Event : null);
                    if (streamToggle && streamToggle.checked === false) {
                        streamToggle.checked = true;
                        if (EvCtor) streamToggle.dispatchEvent?.(new EvCtor('change', { bubbles: true }));
                    }
                }
            } catch (_) {}
        });
        try {
            const stCtx = parentWin.SillyTavern?.getContext?.();
            const evSrc = stCtx?.eventSource;
            const evTypes = stCtx?.event_types || {};
            if (evSrc && typeof evSrc.on === 'function') {
                const bindStEvent = (evName, handler) => {
                    if (!evName) return;
                    evSrc.on(evName, handler);
                    runtime.uiStops.push(() => {
                        try {
                            if (typeof evSrc.removeListener === 'function') evSrc.removeListener(evName, handler);
                            else if (typeof evSrc.off === 'function') evSrc.off(evName, handler);
                            else {
                                const bucket = evSrc.events?.[evName] || evSrc._events?.[evName];
                                if (Array.isArray(bucket)) {
                                    const idx = bucket.indexOf(handler);
                                    if (idx !== -1) bucket.splice(idx, 1);
                                }
                            }
                        } catch (_) {}
                    });
                };
                const fnSanitize = () => {
                    const latestStoryRun = runtime.lastStoryRun || runtime.runHistory.find(r => r?.requestTier === 'story');
                    if (
                        runtime.settings.pluginEnabled !== false
                        && !isPluginOnlyBypassStoryMode()
                        && latestStoryRun?.bypassed !== true
                    ) {
                        sanitizeLatestChatMessageInPlace();
                    }
                };
                const fnSanitizeDelayed = () => {
                    fnSanitize();
                    setTimeout(fnSanitize, 120);
                };
                bindStEvent(evTypes.GENERATION_STARTED || 'generation_started', (genType) => {
                    runtime.lastGenerationType = String(genType || 'normal').toLowerCase();
                });
                bindStEvent(evTypes.MESSAGE_RECEIVED || 'message_received', fnSanitizeDelayed);
                bindStEvent(evTypes.CHARACTER_MESSAGE_RENDERED || 'character_message_rendered', fnSanitizeDelayed);
                bindStEvent(evTypes.GENERATION_ENDED || 'generation_ended', () => {
                    runtime.lastGenerationType = 'normal';
                    fnSanitizeDelayed();
                });
                bindStEvent(evTypes.GENERATION_STOPPED || 'generation_stopped', () => {
                    runtime.lastGenerationType = 'normal';
                    fnSanitizeDelayed();
                    for (const r of Array.from(runtime.activeRuns.values())) {
                        try { r.abort(new DOMException('Clicked stop button', 'AbortError')); } catch (_) {}
                    }
                    setTimeout(() => {
                        try {
                            const doc = hostDocument();
                            const sendBtn = doc?.getElementById?.('send_but');
                            const stopBtn = doc?.getElementById?.('mes_stop');
                            const isVisible = el => {
                                if (!el) return false;
                                const view = doc.defaultView || window;
                                const cs = view.getComputedStyle ? view.getComputedStyle(el) : null;
                                return !(el.classList?.contains('displayNone') || cs?.display === 'none');
                            };
                            if ((sendBtn && !isVisible(sendBtn)) || (stopBtn && isVisible(stopBtn))) {
                                if (typeof stCtx?.activateSendButtons === 'function') {
                                    stCtx.activateSendButtons();
                                }
                            }
                        } catch (_) {}
                    }, 1200);
                });
                const fnSyncToolPreset = () => { if (!runtime.disposed) setTimeout(() => { syncStPostProcessingForToolTransport(); syncConfigPanel(); }, 0); };
                const captureWorldInfoSnapshot = eventData => {
                    try {
                        if (eventData?.dryRun) return;
                        const now = Date.now();
                        const blocks = [];
                        const seen = new Set();
                        const add = txt => {
                            const sTxt = String(txt ?? '').trim();
                            if (!sTxt || sTxt.includes('<%_') || sTxt.includes('<ta_rule_') || sTxt.includes('[TA_NATIVE_DELIVERY]') || sTxt.includes('<inert_lexical_entropy_buffer') || sTxt.includes('<ta_roll_pool>')) return;
                            if (!seen.has(sTxt)) { seen.add(sTxt); blocks.push(sTxt); }
                        };
                        if (runtime.lastWorldInfoSnapshot && (now - (runtime.lastWorldInfoSnapshot.at || 0)) < 3000 && Array.isArray(runtime.lastWorldInfoSnapshot.blocks)) {
                            for (const prevBlk of runtime.lastWorldInfoSnapshot.blocks) add(prevBlk);
                        }
                        if (Array.isArray(eventData)) {
                            for (const ent of eventData) {
                                if (ent?.content) add(ent.content);
                            }
                        }
                        if (Array.isArray(eventData?.chat)) {
                            runtime.lastPromptReadyChat = { at: now, chat: eventData.chat };
                            for (const m of eventData.chat) {
                                if (isStandaloneWorldInfoMsg(m)) {
                                    const t = typeof m.content === 'string' ? m.content : (Array.isArray(m.content) ? m.content.filter(p => p?.type === 'text').map(p => p.text).join('\n') : '');
                                    add(t);
                                }
                            }
                        }
                        if (typeof eventData?.worldInfoBefore === 'string') add(eventData.worldInfoBefore);
                        if (typeof eventData?.worldInfoAfter === 'string') add(eventData.worldInfoAfter);
                        if (blocks.length > 0) {
                            runtime.lastWorldInfoSnapshot = { at: now, blocks };
                        }
                    } catch (_) {}
                };
                bindStEvent(evTypes.WORLD_INFO_ACTIVATED || 'world_info_activated', captureWorldInfoSnapshot);
                bindStEvent(evTypes.CHAT_COMPLETION_PROMPT_READY || 'chat_completion_prompt_ready', captureWorldInfoSnapshot);
                bindStEvent(evTypes.PRESET_CHANGED || 'preset_changed', fnSyncToolPreset);
                bindStEvent(evTypes.OAI_PRESET_CHANGED_AFTER || 'oai_preset_changed_after', fnSyncToolPreset);
            }
        } catch (_) {}

        let autoUpdateTimer = null;
        runtime.uiStops.push(() => {
            if (autoUpdateTimer != null) {
                clearTimeout(autoUpdateTimer);
                autoUpdateTimer = null;
            }
        });
        if (runtime.settings.autoUpdateEnabled !== false) {
            autoUpdateTimer = setTimeout(() => {
                autoUpdateTimer = null;
                if (!runtime.disposed && runtime.settings.autoUpdateEnabled !== false) {
                    checkForUpdate({ manual: false }).catch(() => {});
                }
            }, 3000);
        }

        const launcher = registerLauncher(); try { window.addEventListener('pagehide', () => dispose('pagehide'), { once: true }); } catch (_) {}
        console.log('[' + SCRIPT_NAME + '] loaded', { launcher, settings: runtime.settings }); notify('success', interceptionEnabled() ? 'Loaded; enabled features are active.' : 'Loaded; features are currently disabled.');
    }
    setTimeout(() => { try { init(); } catch (error) { console.error('[' + SCRIPT_NAME + '] initialization failed', error); notify('error', 'Initialization failed: ' + (error?.message || String(error))); } }, 0);
})();
